fn resolve_private_key_source(
    inline: Option<WithOrigin<PrivateKey>>,
    file: Option<WithOrigin<PathBuf>>,
    inline_field: &'static str,
    file_field: &'static str,
    error: ParseError,
    emitter: &mut Emitter<ParseError>,
    files: &ConfigFiles<'_>,
) -> Option<(PrivateKey, ParameterOrigin)> {
    let file = match (inline, file) {
        (Some(_), Some(_)) => {
            emitter.emit(
                Report::new(error).attach(format!(
                    "{inline_field} and {file_field} are mutually exclusive; configure exactly one private-key source"
                )),
            );
            return None;
        }
        (Some(inline), None) => return Some(inline.into_tuple()),
        (None, Some(file)) => file,
        (None, None) => {
            emitter.emit(
                Report::new(error).attach(format!(
                    "missing private-key source; configure exactly one of {inline_field} or {file_field}"
                )),
            );
            return None;
        }
    };
    match read_private_key_file(file, file_field, files) {
        Ok(private_key) => Some(private_key),
        Err(message) => {
            emitter.emit(Report::new(error).attach(message));
            None
        }
    }
}
/// Read one canonical private key from a configured file.
///
/// Launchers that load a `data_dir` node check the custody of the fixed `<data_dir>/secrets/`
/// key files before this parser runs (`irohad::node_secrets::verify_config_key_custody`). The
/// encoded key is read into a zeroizing buffer.
fn read_private_key_file(
    file: WithOrigin<PathBuf>,
    file_field: &'static str,
    files: &ConfigFiles<'_>,
) -> core::result::Result<(PrivateKey, ParameterOrigin), String> {
    let path = file.resolve_relative_path();
    let (_, origin) = file.into_tuple();
    if path.as_os_str().is_empty() {
        return Err(format!("{file_field} must not be empty"));
    }
    let bytes = read_checked(
        files,
        &path,
        ConfigFileRequest {
            access: ConfigFileAccess::Private,
            maximum: MAX_PRIVATE_KEY_FILE_BYTES,
        },
    )
    .map_err(|error| format!("failed to read {file_field} `{}`: {error}", path.display()))?;
    let encoded = std::str::from_utf8(&bytes)
        .map_err(|_| format!("{file_field} `{}` must contain UTF-8", path.display()))?;
    let encoded = encoded
        .strip_suffix("\r\n")
        .or_else(|| encoded.strip_suffix('\n'))
        .unwrap_or(encoded);
    if encoded.is_empty() || encoded.bytes().any(|byte| matches!(byte, b'\r' | b'\n')) {
        return Err(format!(
            "{file_field} `{}` must contain exactly one canonical private key",
            path.display()
        ));
    }
    PrivateKey::from_str(encoded)
        .map(|private_key| (private_key, origin))
        .map_err(|err| {
            format!(
                "{file_field} `{}` does not contain a canonical private key: {err}",
                path.display()
            )
        })
}
fn resolve_genesis_identity_source(
    inline: Option<WithOrigin<NetworkId>>,
    file: Option<WithOrigin<PathBuf>>,
    inline_field: &'static str,
    file_field: &'static str,
    error: ParseError,
    emitter: &mut Emitter<ParseError>,
    files: &ConfigFiles<'_>,
) -> Option<HashOf<BlockHeader>> {
    let file = match (inline, file) {
        (Some(_), Some(_)) => {
            emitter.emit(Report::new(error).attach(format!(
                "{inline_field} and {file_field} are mutually exclusive; configure exactly one public identity source"
            )));
            return None;
        }
        (Some(inline), None) => return Some(inline.into_value().into_genesis_hash()),
        (None, Some(file)) => file,
        (None, None) => {
            emitter.emit(Report::new(error).attach(format!(
                "missing public identity source; configure exactly one of {inline_field} or {file_field}"
            )));
            return None;
        }
    };
    match read_network_identity_file(file, file_field, files) {
        Ok((identity, _)) => Some(identity.into_genesis_hash()),
        Err(message) => {
            emitter.emit(Report::new(error).attach(message));
            None
        }
    }
}
fn read_network_identity_file(
    file: WithOrigin<PathBuf>,
    file_field: &'static str,
    files: &ConfigFiles<'_>,
) -> core::result::Result<(NetworkId, ParameterOrigin), String> {
    let path = file.resolve_relative_path();
    let (_, origin) = file.into_tuple();
    if path.as_os_str().is_empty() {
        return Err(format!("{file_field} must not be empty"));
    }
    let bytes = read_checked(
        files,
        &path,
        ConfigFileRequest {
            access: ConfigFileAccess::Public,
            maximum: MAX_PUBLIC_IDENTITY_FILE_BYTES,
        },
    )
    .map_err(|error| format!("failed to read {file_field} `{}`: {error}", path.display()))?;
    let encoded = std::str::from_utf8(&bytes)
        .map_err(|_| format!("{file_field} `{}` must contain UTF-8", path.display()))?;
    let Some(identity_text) = encoded.strip_suffix('\n') else {
        return Err(format!(
            "{file_field} `{}` must contain exactly one LF-terminated canonical public identity",
            path.display()
        ));
    };
    if identity_text.is_empty()
        || identity_text
            .bytes()
            .any(|byte| matches!(byte, b'\r' | b'\n'))
    {
        return Err(format!(
            "{file_field} `{}` must contain exactly one LF-terminated canonical public identity",
            path.display()
        ));
    }
    let identity = NetworkId::from_str(identity_text).map_err(|err| {
        format!(
            "{file_field} `{}` does not contain a valid public identity: {err}",
            path.display()
        )
    })?;
    if encoded != format!("{identity}\n") {
        return Err(format!(
            "{file_field} `{}` does not contain the canonical public identity spelling",
            path.display()
        ));
    }
    Ok((identity, origin))
}
