impl Governance {
    /// Convert user-supplied governance settings into the runtime representation.
    pub fn parse(self) -> actual::Governance {
        let parliament_tle_partial_release_signer_provider_policy_digest =
            validate_consensus_signer_provider_binding_v1(
                self.parliament_tle_partial_release_signer_provider_handle
                    .as_deref(),
                self.parliament_tle_partial_release_signer_provider_revision,
                self.parliament_tle_partial_release_signer_provider_policy_digest_hex
                    .as_deref(),
            )
            .expect("invalid Parliament TLE partial-release signer provider binding");
        assert!(
            self.min_enactment_delay > 0,
            "min_enactment_delay must be non-zero"
        );
        assert!(
            self.conviction_step_blocks > 0,
            "governance.conviction_step_blocks must be non-zero"
        );
        assert!(
            self.max_conviction > 0,
            "governance.max_conviction must be non-zero"
        );
        assert!(
            self.approval_threshold_q_den > 0,
            "governance.approval_threshold_q_den must be non-zero"
        );
        assert!(
            self.approval_threshold_q_num <= self.approval_threshold_q_den,
            "governance.approval_threshold_q_num must not exceed governance.approval_threshold_q_den"
        );
        assert!(
            self.parliament_sortition_pulse_delay_blocks > 0,
            "parliament_sortition_pulse_delay_blocks must be non-zero"
        );
        assert!(
            self.parliament_invitation_phase_blocks > 0,
            "parliament_invitation_phase_blocks must be non-zero"
        );
        assert!(
            self.parliament_public_finding_phase_blocks > 0,
            "parliament_public_finding_phase_blocks must be non-zero"
        );
        let maximum_parliament_body_size = usize::try_from(MAX_PARLIAMENT_BODY_TARGET_SEATS_V1)
            .expect("Parliament body target bound fits usize");
        assert!(
            self.parliament_alternate_size <= maximum_parliament_body_size,
            "parliament_alternate_size must be within 0..={MAX_PARLIAMENT_BODY_TARGET_SEATS_V1}"
        );
        for (name, size) in [
            ("rules_committee_size", self.rules_committee_size),
            ("agenda_council_size", self.agenda_council_size),
            ("interest_panel_size", self.interest_panel_size),
            ("review_panel_size", self.review_panel_size),
            ("coordination_council_size", self.coordination_council_size),
            ("policy_jury_size", self.policy_jury_size),
            ("confirmation_jury_size", self.confirmation_jury_size),
            ("oversight_committee_size", self.oversight_committee_size),
            ("mpc_committee_size", self.mpc_committee_size),
            ("fma_committee_size", self.fma_committee_size),
        ] {
            assert!(
                (1..=maximum_parliament_body_size).contains(&size),
                "{name} must be within 1..={MAX_PARLIAMENT_BODY_TARGET_SEATS_V1}"
            );
        }
        for (name, size) in [
            ("policy_jury_size", self.policy_jury_size),
            ("confirmation_jury_size", self.confirmation_jury_size),
        ] {
            let minimum_hidden_body_size =
                usize::try_from(MIN_PARLIAMENT_HIDDEN_BALLOT_ANONYMITY_V1)
                    .expect("Parliament anonymity floor fits usize");
            assert!(
                (minimum_hidden_body_size..=maximum_parliament_body_size).contains(&size),
                "{name} must be within {MIN_PARLIAMENT_HIDDEN_BALLOT_ANONYMITY_V1}..={MAX_PARLIAMENT_BODY_TARGET_SEATS_V1} because exact hidden-ballot tallies require the canonical anonymity floor"
            );
        }
        let parliament_timed_ovn = self.parliament_timed_ovn.parse();
        let parliament_tle_key_lifecycle = self.parliament_tle_key_lifecycle.parse();
        let maximum_hidden_body_size = self.policy_jury_size.max(self.confirmation_jury_size);
        assert!(
            usize::try_from(parliament_timed_ovn.max_corpus_entries)
                .is_ok_and(|max_corpus_entries| max_corpus_entries >= maximum_hidden_body_size),
            "governance.parliament_timed_ovn.max_corpus_entries must cover the largest hidden-ballot body (max(policy_jury_size, confirmation_jury_size)={maximum_hidden_body_size})"
        );
        let viral_incentives = actual::ViralIncentives {
            incentive_pool_account: parse_account_id_literal(
                &self.viral_incentive_pool_account,
                "invalid viral incentive pool account id",
            ),
            escrow_account: parse_account_id_literal(
                &self.viral_escrow_account,
                "invalid viral escrow account id",
            ),
            reward_asset_definition_id: self
                .viral_reward_asset_id
                .parse()
                .expect("invalid viral reward asset id"),
            follow_reward_amount: self.viral_follow_reward_amount,
            sender_bonus_amount: self.viral_sender_bonus_amount,
            max_daily_claims_per_uaid: self.viral_max_daily_claims_per_uaid,
            max_claims_per_binding: self.viral_max_claims_per_binding,
            daily_budget: self.viral_daily_budget,
            halt: self.viral_halt,
            promo_starts_at_ms: self.viral_promo_start_ms,
            promo_ends_at_ms: self.viral_promo_end_ms,
            campaign_cap: self.viral_campaign_cap,
            deny_uaids: self
                .viral_deny_uaids
                .iter()
                .map(|uaid| uaid.parse().expect("invalid viral deny UAID"))
                .collect(),
            deny_binding_digests: self
                .viral_deny_binding_hashes
                .iter()
                .map(|hash| Hash::from_str(hash).expect("invalid viral deny binding digest"))
                .collect(),
        };
        if let (Some(start), Some(end)) = (
            viral_incentives.promo_starts_at_ms,
            viral_incentives.promo_ends_at_ms,
        ) {
            assert!(
                start < end,
                "viral promotion start must precede end (start={start}, end={end})"
            );
        }
        let jdg_signature_schemes = normalize_jdg_signature_schemes(self.jdg_signature_schemes);
        let runtime_upgrade_provenance = self.runtime_upgrade_provenance.parse();
        actual::Governance {
            // Relation-selecting keys are committed per election; a node names none.
            vk_ballot: None,
            vk_tally: None,
            voting_asset_id: self
                .voting_asset_id
                .parse()
                .expect("invalid governance voting asset id"),
            citizenship_asset_id: self
                .citizenship_asset_id
                .parse()
                .expect("invalid citizenship asset id"),
            citizenship_bond_amount: self.citizenship_bond_amount,
            citizenship_escrow_account: parse_account_id_literal(
                &self.citizenship_escrow_account,
                "invalid citizenship escrow account id",
            ),
            min_bond_amount: self.min_bond_amount,
            bond_escrow_account: parse_account_id_literal(
                &self.bond_escrow_account,
                "invalid governance bond escrow account id",
            ),
            slash_receiver_account: parse_account_id_literal(
                &self.slash_receiver_account,
                "invalid governance slash receiver account id",
            ),
            slash_double_vote_bps: self.slash_double_vote_bps,
            slash_invalid_proof_bps: self.slash_invalid_proof_bps,
            slash_ineligible_proof_bps: self.slash_ineligible_proof_bps,
            alias_teu_minimum: self.alias_teu_minimum,
            alias_frontier_telemetry: self.alias_frontier_telemetry,
            debug_trace_pipeline: self.debug_trace_pipeline,
            jdg_signature_schemes,
            runtime_upgrade_provenance,
            viral_incentives,
            sorafs_pin_policy: self.sorafs_pin_policy.parse(),
            sorafs_pin_fee_asset_id: self
                .sorafs_pin_fee_asset_id
                .parse()
                .expect("invalid SoraFS pin fee asset id"),
            sorafs_pin_fee_treasury_account: parse_account_id_literal(
                &self.sorafs_pin_fee_treasury_account,
                "invalid SoraFS pin fee treasury account id",
            ),
            sorafs_pricing: PricingScheduleRecord::launch_default(),
            sorafs_penalty: self.sorafs_penalty.parse(),
            sorafs_telemetry: self.sorafs_telemetry.parse(),
            sorafs_provider_owners: {
                let mut bindings = BTreeMap::new();
                for (provider, owner) in self.sorafs_provider_owners {
                    let trimmed = provider.trim_start_matches("0x");
                    let bytes = hex::decode(trimmed).unwrap_or_else(|err| {
                        panic!("invalid SoraFS provider id {provider}: {err}");
                    });
                    let array: [u8; 32] = bytes.try_into().unwrap_or_else(|_| {
                        panic!("SoraFS provider id {provider} must be 32 bytes")
                    });
                    let provider_id = ProviderId::new(array);
                    let owner_id = parse_account_id_literal(
                        &owner,
                        &format!("invalid SoraFS provider owner {owner}"),
                    );
                    assert!(
                        bindings.insert(provider_id, owner_id).is_none(),
                        "duplicate SoraFS provider binding for {provider}"
                    )
                }
                bindings
            },
            conviction_step_blocks: self.conviction_step_blocks,
            max_conviction: self.max_conviction,
            min_enactment_delay: self.min_enactment_delay,
            window_span: self.window_span,
            max_active_referenda: self.max_active_referenda,
            max_lock_owners_per_referendum: self.max_lock_owners_per_referendum,
            plain_voting_enabled: self.plain_voting_enabled,
            approval_threshold_q_num: self.approval_threshold_q_num,
            approval_threshold_q_den: self.approval_threshold_q_den,
            min_turnout: self.min_turnout,
            parliament_alternate_size: self.parliament_alternate_size,
            parliament_sortition_pulse_delay_blocks: self.parliament_sortition_pulse_delay_blocks,
            parliament_invitation_phase_blocks: self.parliament_invitation_phase_blocks,
            parliament_public_finding_phase_blocks: self.parliament_public_finding_phase_blocks,
            parliament_timed_ovn,
            parliament_tle_key_lifecycle,
            parliament_tle_partial_release_signer_provider_handle: self
                .parliament_tle_partial_release_signer_provider_handle,
            parliament_tle_partial_release_signer_provider_revision: self
                .parliament_tle_partial_release_signer_provider_revision,
            parliament_tle_partial_release_signer_provider_policy_digest,
            rules_committee_size: self.rules_committee_size,
            agenda_council_size: self.agenda_council_size,
            interest_panel_size: self.interest_panel_size,
            review_panel_size: self.review_panel_size,
            coordination_council_size: self.coordination_council_size,
            policy_jury_size: self.policy_jury_size,
            confirmation_jury_size: self.confirmation_jury_size,
            oversight_committee_size: self.oversight_committee_size,
            mpc_committee_size: self.mpc_committee_size,
            fma_committee_size: self.fma_committee_size,
        }
    }
}
#[cfg(test)]
mod governance_tests {
    use super::*;
    use iroha_config_base::{read::ConfigReader, toml::TomlSource};

    #[test]
    fn parliament_sortition_pulse_delay_is_file_configured_nonzero_and_defaults_to_four() {
        let table: toml::Table = toml::from_str("parliament_sortition_pulse_delay_blocks = 7")
            .expect("parse Parliament sortition delay TOML");
        let parsed = ConfigReader::new()
            .with_toml_source(TomlSource::inline(table))
            .read_and_complete::<Governance>()
            .expect("read Governance with sortition delay")
            .parse();
        assert_eq!(parsed.parliament_sortition_pulse_delay_blocks, 7);

        assert_eq!(
            Governance::default()
                .parse()
                .parliament_sortition_pulse_delay_blocks,
            defaults::governance::PARLIAMENT_SORTITION_PULSE_DELAY_BLOCKS
        );
        assert_eq!(
            defaults::governance::PARLIAMENT_SORTITION_PULSE_DELAY_BLOCKS,
            4
        );

        let invalid = Governance {
            parliament_sortition_pulse_delay_blocks: 0,
            ..Governance::default()
        };
        assert!(
            std::panic::catch_unwind(|| invalid.parse()).is_err(),
            "zero sortition delay must fail before an attempt can be created"
        );
    }

    #[test]
    fn parliament_invitation_window_is_file_configured_and_nonzero() {
        let table: toml::Table = toml::from_str("parliament_invitation_phase_blocks = 17")
            .expect("parse Parliament invitation policy TOML");
        let parsed = ConfigReader::new()
            .with_toml_source(TomlSource::inline(table))
            .read_and_complete::<Governance>()
            .expect("read Governance with invitation policy")
            .parse();

        assert_eq!(parsed.parliament_invitation_phase_blocks, 17);
    }

    #[test]
    fn parliament_public_finding_window_is_file_configured_and_nonzero() {
        let table: toml::Table = toml::from_str("parliament_public_finding_phase_blocks = 19")
            .expect("parse Parliament public-finding policy TOML");
        let parsed = ConfigReader::new()
            .with_toml_source(TomlSource::inline(table))
            .read_and_complete::<Governance>()
            .expect("read Governance with public-finding policy")
            .parse();

        assert_eq!(parsed.parliament_public_finding_phase_blocks, 19);

        let invalid = Governance {
            parliament_public_finding_phase_blocks: 0,
            ..Governance::default()
        };
        assert!(
            std::panic::catch_unwind(|| invalid.parse()).is_err(),
            "zero public-finding phase must fail before Reflection can be entered"
        );
    }

    #[test]
    fn parliament_public_finding_window_defaults_to_one_hour_at_one_second_blocks() {
        let parsed = Governance::default().parse();
        assert_eq!(
            parsed.parliament_public_finding_phase_blocks,
            defaults::governance::PARLIAMENT_PUBLIC_FINDING_PHASE_BLOCKS
        );
        assert_eq!(parsed.parliament_public_finding_phase_blocks, 3_600);
    }

    #[test]
    fn governance_cardinality_bounds_are_file_configured_nonzero_and_defaulted() {
        let table: toml::Table =
            toml::from_str("max_active_referenda = 7\nmax_lock_owners_per_referendum = 11")
                .expect("parse governance cardinality bounds TOML");
        let parsed = ConfigReader::new()
            .with_toml_source(TomlSource::inline(table))
            .read_and_complete::<Governance>()
            .expect("read Governance with cardinality bounds")
            .parse();

        assert_eq!(parsed.max_active_referenda.get(), 7);
        assert_eq!(parsed.max_lock_owners_per_referendum.get(), 11);

        let defaults = Governance::default().parse();
        assert_eq!(
            defaults.max_active_referenda,
            crate::parameters::defaults::governance::MAX_ACTIVE_REFERENDA
        );
        assert_eq!(
            defaults.max_lock_owners_per_referendum,
            crate::parameters::defaults::governance::MAX_LOCK_OWNERS_PER_REFERENDUM
        );

        for field in ["max_active_referenda", "max_lock_owners_per_referendum"] {
            let table: toml::Table =
                toml::from_str(&format!("{field} = 0")).expect("parse zero governance bound TOML");
            assert!(
                ConfigReader::new()
                    .with_toml_source(TomlSource::inline(table))
                    .read_and_complete::<Governance>()
                    .is_err(),
                "{field} must reject zero during configuration loading"
            );
        }
    }

    #[test]
    fn parliament_enactment_delay_rejects_zero_at_startup() {
        let governance = Governance {
            min_enactment_delay: 0,
            ..Governance::default()
        };
        let panic = std::panic::catch_unwind(|| governance.parse());
        assert!(
            panic.is_err(),
            "zero enactment delay must fail before a proposal can become stranded"
        );
    }

    #[test]
    #[should_panic(expected = "governance.approval_threshold_q_den must be non-zero")]
    fn governance_approval_threshold_rejects_zero_denominator() {
        Governance {
            approval_threshold_q_den: 0,
            ..Governance::default()
        }
        .parse();
    }

    #[test]
    #[should_panic(
        expected = "governance.approval_threshold_q_num must not exceed governance.approval_threshold_q_den"
    )]
    fn governance_approval_threshold_rejects_numerator_above_denominator() {
        Governance {
            approval_threshold_q_num: 3,
            approval_threshold_q_den: 2,
            ..Governance::default()
        }
        .parse();
    }

    #[test]
    fn governance_approval_threshold_accepts_closed_unit_interval_boundaries() {
        for (numerator, denominator) in [(0, 1), (1, 1)] {
            let parsed = Governance {
                approval_threshold_q_num: numerator,
                approval_threshold_q_den: denominator,
                ..Governance::default()
            }
            .parse();
            assert_eq!(parsed.approval_threshold_q_num, numerator);
            assert_eq!(parsed.approval_threshold_q_den, denominator);
        }
    }

    #[test]
    #[should_panic(expected = "governance.conviction_step_blocks must be non-zero")]
    fn governance_conviction_step_rejects_zero() {
        Governance {
            conviction_step_blocks: 0,
            ..Governance::default()
        }
        .parse();
    }

    #[test]
    #[should_panic(expected = "governance.max_conviction must be non-zero")]
    fn governance_max_conviction_rejects_zero() {
        Governance {
            max_conviction: 0,
            ..Governance::default()
        }
        .parse();
    }

    #[test]
    fn parliament_timed_ovn_file_config_parses_deterministic_height_windows() {
        let table: toml::Table = toml::from_str(
            r"
policy_jury_size = 16
confirmation_jury_size = 16

[parliament_timed_ovn]
registration_phase_blocks = 17
survivor_freeze_phase_blocks = 16
commitment_phase_blocks = 13
release_delay_blocks = 14
opening_phase_blocks = 15
max_ballot_retries = 15
max_corpus_entries = 16
",
        )
        .expect("parse timed-OVN policy TOML");
        let parsed = ConfigReader::new()
            .with_toml_source(TomlSource::inline(table))
            .read_and_complete::<Governance>()
            .expect("read Governance with timed-OVN policy")
            .parse()
            .parliament_timed_ovn;

        assert_eq!(
            parsed,
            actual::ParliamentTimedOvn {
                registration_phase_blocks: 17,
                survivor_freeze_phase_blocks: 16,
                commitment_phase_blocks: 13,
                release_delay_blocks: 14,
                opening_phase_blocks: 15,
                max_ballot_retries: 15,
                max_corpus_entries: 16,
            }
        );
        assert_eq!(parsed.checked_attempt_span_blocks(), Some(75));
        assert_eq!(parsed.checked_max_lifecycle_span_blocks(), Some(1_200));
    }

    #[test]
    fn parliament_timed_ovn_defaults_are_bounded_and_valid() {
        let parsed = ParliamentTimedOvn::default().parse();

        assert_eq!(parsed.checked_attempt_span_blocks(), Some(9_400));
        assert_eq!(parsed.checked_max_lifecycle_span_blocks(), Some(37_600));
        assert_eq!(
            parsed.opening_phase_blocks,
            defaults::governance::parliament_timed_ovn::OPENING_PHASE_BLOCKS
        );
        assert_eq!(parsed.opening_phase_blocks, 600);
        assert!(
            parsed.max_ballot_retries
                <= defaults::governance::parliament_timed_ovn::MAX_BALLOT_RETRIES_LIMIT
        );
        assert_eq!(
            defaults::governance::parliament_timed_ovn::MAX_BALLOT_RETRIES_LIMIT,
            16
        );
        assert_eq!(
            parsed.max_corpus_entries,
            u32::try_from(iroha_crypto::timed_ovn::TIMED_OVN_MAX_PARTICIPANTS_V1)
                .expect("timed-OVN participant limit fits u32")
        );
        assert_eq!(
            defaults::governance::parliament_timed_ovn::MAX_CORPUS_ENTRIES_LIMIT,
            1_000
        );

        let no_retries = actual::ParliamentTimedOvn {
            max_ballot_retries: 0,
            ..parsed
        };
        no_retries.assert_valid();
        let maximum_retries = actual::ParliamentTimedOvn {
            max_ballot_retries:
                defaults::governance::parliament_timed_ovn::MAX_BALLOT_RETRIES_LIMIT,
            ..parsed
        };
        maximum_retries.assert_valid();
        let minimum_maximum_corpus_window = actual::ParliamentTimedOvn {
            commitment_phase_blocks: 32,
            max_corpus_entries: 1_000,
            ..parsed
        };
        minimum_maximum_corpus_window.assert_valid();
    }

    #[test]
    fn parliament_timed_ovn_rejects_zero_overflow_and_resource_overruns() {
        let valid = actual::ParliamentTimedOvn::default();
        let invalid = [
            actual::ParliamentTimedOvn {
                registration_phase_blocks: 0,
                ..valid
            },
            actual::ParliamentTimedOvn {
                survivor_freeze_phase_blocks: 0,
                ..valid
            },
            actual::ParliamentTimedOvn {
                commitment_phase_blocks: 0,
                ..valid
            },
            actual::ParliamentTimedOvn {
                commitment_phase_blocks: 31,
                max_corpus_entries: 1_000,
                ..valid
            },
            actual::ParliamentTimedOvn {
                registration_phase_blocks: 1_000,
                max_corpus_entries: 1_000,
                ..valid
            },
            actual::ParliamentTimedOvn {
                survivor_freeze_phase_blocks: 999,
                max_corpus_entries: 1_000,
                ..valid
            },
            actual::ParliamentTimedOvn {
                release_delay_blocks: 0,
                ..valid
            },
            actual::ParliamentTimedOvn {
                opening_phase_blocks: 0,
                ..valid
            },
            actual::ParliamentTimedOvn {
                registration_phase_blocks: u64::MAX,
                ..valid
            },
            actual::ParliamentTimedOvn {
                registration_phase_blocks: u64::MAX / 2,
                max_ballot_retries:
                    defaults::governance::parliament_timed_ovn::MAX_BALLOT_RETRIES_LIMIT,
                ..valid
            },
            actual::ParliamentTimedOvn {
                max_ballot_retries:
                    defaults::governance::parliament_timed_ovn::MAX_BALLOT_RETRIES_LIMIT + 1,
                ..valid
            },
            actual::ParliamentTimedOvn {
                max_corpus_entries: 0,
                ..valid
            },
            actual::ParliamentTimedOvn {
                max_corpus_entries: MIN_PARLIAMENT_HIDDEN_BALLOT_ANONYMITY_V1 - 1,
                ..valid
            },
            actual::ParliamentTimedOvn {
                max_corpus_entries:
                    defaults::governance::parliament_timed_ovn::MAX_CORPUS_ENTRIES_LIMIT + 1,
                ..valid
            },
        ];

        for policy in invalid {
            assert!(
                std::panic::catch_unwind(|| policy.assert_valid()).is_err(),
                "invalid timed-OVN policy must fail closed: {policy:?}"
            );
        }
    }

    #[test]
    fn parliament_timed_ovn_corpus_covers_every_hidden_body_seat() {
        let mut governance = Governance::default();
        governance.parliament_timed_ovn.max_corpus_entries = 499;
        governance.parliament_timed_ovn.registration_phase_blocks = 500;
        governance.parliament_timed_ovn.survivor_freeze_phase_blocks = 499;
        governance.policy_jury_size = 500;
        governance.confirmation_jury_size = 499;

        assert!(
            std::panic::catch_unwind(|| governance.parse()).is_err(),
            "a hidden body larger than the timed-OVN corpus must fail at startup"
        );
    }

    #[test]
    fn parliament_hidden_body_sizes_require_the_anonymity_floor() {
        let one_policy_seat = Governance {
            policy_jury_size: 1,
            ..Governance::default()
        };
        assert!(
            std::panic::catch_unwind(|| one_policy_seat.parse()).is_err(),
            "a single-seat Policy Jury is below the hidden-ballot anonymity floor"
        );

        let two_policy_seats = Governance {
            policy_jury_size: 2,
            ..Governance::default()
        };
        assert!(
            std::panic::catch_unwind(|| two_policy_seats.parse()).is_err(),
            "a two-seat Policy Jury would expose choices through the exact tally"
        );

        let one_confirmation_seat = Governance {
            confirmation_jury_size: 1,
            ..Governance::default()
        };
        assert!(
            std::panic::catch_unwind(|| one_confirmation_seat.parse()).is_err(),
            "a single-seat Confirmation Jury is below the hidden-ballot anonymity floor"
        );

        let two_confirmation_seats = Governance {
            confirmation_jury_size: 2,
            ..Governance::default()
        };
        assert!(
            std::panic::catch_unwind(|| two_confirmation_seats.parse()).is_err(),
            "a two-seat Confirmation Jury would expose choices through the exact tally"
        );

        let one_public_seat = Governance {
            rules_committee_size: 1,
            agenda_council_size: 1,
            interest_panel_size: 1,
            review_panel_size: 1,
            coordination_council_size: 1,
            oversight_committee_size: 1,
            mpc_committee_size: 1,
            fma_committee_size: 1,
            ..Governance::default()
        };
        one_public_seat.parse();
    }

    #[test]
    fn debug_trace_pipeline_defaults_false() {
        let cfg = Governance::default();
        assert!(!cfg.debug_trace_pipeline);
        let parsed = cfg.parse();
        assert!(!parsed.debug_trace_pipeline);
    }
    #[test]
    fn debug_trace_pipeline_roundtrips() {
        let cfg = Governance {
            debug_trace_pipeline: true,
            ..Governance::default()
        };
        let parsed = cfg.parse();
        assert!(parsed.debug_trace_pipeline);
    }
    #[test]
    fn jdg_signature_schemes_defaults_to_simple_threshold() {
        let cfg = Governance::default();
        let parsed = cfg.parse();
        assert!(
            parsed
                .jdg_signature_schemes
                .contains(&JdgSignatureScheme::SimpleThreshold)
        );
    }
    #[test]
    fn jdg_signature_schemes_rejects_aliases() {
        let cfg = Governance {
            jdg_signature_schemes: vec!["simple".to_string(), "bls-aggregate".to_string()],
            ..Governance::default()
        };
        assert!(
            std::panic::catch_unwind(|| cfg.parse()).is_err(),
            "first-release configuration must reject noncanonical aliases"
        );
    }
}
/// User-level configuration container for `Concurrency`.
