/// Cursor handling mode for server-facing iterable queries (user view).
/// User-level enumeration translating `QueryCursorMode` settings.
#[derive(Debug, Clone, Copy, PartialEq, Eq, strum::EnumString, strum::Display)]
#[strum(serialize_all = "snake_case")]
pub enum QueryCursorMode {
    /// Keep cursor state only in memory; abandon it when the client disconnects.
    Ephemeral,
    /// Persist cursor state so it survives node restarts and client reconnects.
    Stored,
}
impl QueryCursorMode {
    fn into_actual(self) -> actual::QueryCursorMode {
        match self {
            QueryCursorMode::Ephemeral => actual::QueryCursorMode::Ephemeral,
            QueryCursorMode::Stored => actual::QueryCursorMode::Stored,
        }
    }
}
impl json::JsonSerialize for QueryCursorMode {
    fn json_serialize(&self, out: &mut String) {
        json::write_json_string(&self.to_string(), out);
    }
}
impl json::JsonDeserialize for QueryCursorMode {
    fn json_deserialize(
        parser: &mut json::Parser<'_>,
    ) -> ::core::result::Result<Self, json::Error> {
        let text = parser.parse_string()?;
        Self::from_str(&text).map_err(|err| json::Error::InvalidField {
            field: "query_cursor_mode".into(),
            message: err.to_string(),
        })
    }
}
#[cfg(test)]
mod pipeline_tests {
    use super::*;
    use crate::parameters::defaults;
    fn pipeline_with_debug(trace_scheduler_inputs: bool, trace_tx_eval: bool) -> Pipeline {
        Pipeline {
            access_set_cache_enabled: defaults::pipeline::ACCESS_SET_CACHE_ENABLED,
            parallel_overlay: defaults::pipeline::PARALLEL_OVERLAY,
            workers: defaults::pipeline::WORKERS,
            stateless_cache_cap: defaults::pipeline::STATELESS_CACHE_CAP,
            parallel_apply: defaults::pipeline::PARALLEL_APPLY,
            ready_queue_heap: defaults::pipeline::READY_QUEUE_HEAP,
            gpu_key_bucket: defaults::pipeline::GPU_KEY_BUCKET,
            debug_trace_scheduler_inputs: trace_scheduler_inputs,
            debug_trace_tx_eval: trace_tx_eval,
            signature_batch_max_ed25519: defaults::pipeline::SIGNATURE_BATCH_MAX_ED25519,
            signature_batch_max_secp256k1: defaults::pipeline::SIGNATURE_BATCH_MAX_SECP256K1,
            signature_batch_max_pqc: defaults::pipeline::SIGNATURE_BATCH_MAX_PQC,
            signature_batch_max_bls: defaults::pipeline::SIGNATURE_BATCH_MAX_BLS,
            cache_size: defaults::pipeline::CACHE_SIZE,
            ivm_cache_max_decoded_ops: defaults::pipeline::IVM_CACHE_MAX_DECODED_OPS,
            ivm_cache_max_bytes: defaults::pipeline::IVM_CACHE_MAX_BYTES,
            ivm_execution_max_bytes: defaults::pipeline::IVM_EXECUTION_MAX_BYTES,
            state_capture: StateCapture {
                source_elements: defaults::pipeline::state_capture::SOURCE_ELEMENTS,
                source_variable_bytes: defaults::pipeline::state_capture::SOURCE_VARIABLE_BYTES,
                source_table_pass_rows: defaults::pipeline::state_capture::SOURCE_TABLE_PASS_ROWS,
                source_lookup_index_entries:
                    defaults::pipeline::state_capture::SOURCE_LOOKUP_INDEX_ENTRIES,
                source_model_operations: defaults::pipeline::state_capture::SOURCE_MODEL_OPERATIONS,
                source_signature_checks: defaults::pipeline::state_capture::SOURCE_SIGNATURE_CHECKS,
                native_work_per_attempt: defaults::pipeline::state_capture::NATIVE_WORK_PER_ATTEMPT,
                table_count: defaults::pipeline::state_capture::TABLE_COUNT,
                table_rows: defaults::pipeline::state_capture::TABLE_ROWS,
                table_payload_bytes: defaults::pipeline::state_capture::TABLE_PAYLOAD_BYTES,
                table_ordered_bytes: defaults::pipeline::state_capture::TABLE_ORDERED_BYTES,
                table_streamed_value_bytes:
                    defaults::pipeline::state_capture::TABLE_STREAMED_VALUE_BYTES,
                total_table_rows: defaults::pipeline::state_capture::TOTAL_TABLE_ROWS,
                encoding_work_per_attempt:
                    defaults::pipeline::state_capture::ENCODING_WORK_PER_ATTEMPT,
            },
            ivm_prover_threads: defaults::pipeline::IVM_PROVER_THREADS,
            query_default_cursor_mode: QueryCursorMode::Ephemeral,
        }
    }
    #[test]
    fn state_capture_defaults_are_complete_and_independent_of_memory() {
        use iroha_config_base::{read::ConfigReader, toml::TomlSource};
        let table = toml::from_str("ivm_execution_max_bytes = 0").unwrap();
        let user = ConfigReader::new()
            .with_toml_source(TomlSource::inline(table))
            .read_and_complete::<Pipeline>()
            .unwrap();
        let mut emitter = Emitter::new();
        let actual = user.parse(&mut emitter);
        emitter.into_result().unwrap();
        assert_eq!(actual.ivm_execution_max_bytes, 0);
        assert_eq!(actual.state_capture, actual::StateCapture::default());
        assert!(actual.state_capture.source_elements > 0);
        assert!(actual.state_capture.source_variable_bytes > 0);
        assert!(actual.state_capture.source_table_pass_rows > 0);
        assert!(actual.state_capture.source_lookup_index_entries > 0);
        assert!(actual.state_capture.source_model_operations > 0);
        assert!(actual.state_capture.source_signature_checks > 0);
        assert!(actual.state_capture.native_work_per_attempt > 0);
        assert!(actual.state_capture.table_count > 0);
        assert!(actual.state_capture.table_rows > 0);
        assert!(actual.state_capture.table_payload_bytes > 0);
        assert!(actual.state_capture.table_ordered_bytes > 0);
        assert!(actual.state_capture.table_streamed_value_bytes > 0);
        assert!(actual.state_capture.total_table_rows > 0);
        assert!(actual.state_capture.encoding_work_per_attempt > 0);
    }

    #[test]
    fn state_capture_explicit_zero_and_each_override_reach_the_actual_owner() {
        use iroha_config_base::{read::ConfigReader, toml::TomlSource};
        let table = toml::from_str(
            r"[state_capture]
source_elements = 0
source_variable_bytes = 1
source_table_pass_rows = 2
source_lookup_index_entries = 3
source_model_operations = 4
source_signature_checks = 5
native_work_per_attempt = 6
table_count = 7
table_rows = 8
table_payload_bytes = 9
table_ordered_bytes = 10
table_streamed_value_bytes = 11
total_table_rows = 12
encoding_work_per_attempt = 13
",
        )
        .unwrap();
        let user = ConfigReader::new()
            .with_toml_source(TomlSource::inline(table))
            .read_and_complete::<Pipeline>()
            .unwrap();
        let mut emitter = Emitter::new();
        let actual = user.parse(&mut emitter);
        emitter.into_result().unwrap();
        assert_eq!(
            actual.state_capture,
            actual::StateCapture {
                source_elements: 0,
                source_variable_bytes: 1,
                source_table_pass_rows: 2,
                source_lookup_index_entries: 3,
                source_model_operations: 4,
                source_signature_checks: 5,
                native_work_per_attempt: 6,
                table_count: 7,
                table_rows: 8,
                table_payload_bytes: 9,
                table_ordered_bytes: 10,
                table_streamed_value_bytes: 11,
                total_table_rows: 12,
                encoding_work_per_attempt: 13,
            }
        );
        assert_eq!(
            actual.ivm_execution_max_bytes,
            defaults::pipeline::IVM_EXECUTION_MAX_BYTES
        );
    }

    #[test]
    fn pipeline_gas_is_not_node_configuration() {
        use iroha_config_base::{read::ConfigReader, toml::TomlSource};
        for source in [
            "[gas]\ntech_account_id = \"local\"",
            "[gas]\naccepted_assets = []",
            "[[gas.units_per_gas]]\nasset = \"local\"\nunits_per_gas = 1",
        ] {
            let table: toml::Table = toml::from_str(source).unwrap();
            let error = ConfigReader::new()
                .with_toml_source(TomlSource::inline(table))
                .read_and_complete::<Pipeline>()
                .expect_err("fee policy is committed, not node configuration");
            assert!(format!("{error:?}").contains("unknown parameter"));
        }
        let mut emitter = Emitter::new();
        let parsed = pipeline_with_debug(false, false).parse(&mut emitter);
        emitter.into_result().unwrap();
        assert_eq!(parsed.gas, actual::Gas::default());
    }

    #[test]
    fn pipeline_parse_maps_debug_flags() {
        let mut emitter = Emitter::new();
        let baseline = pipeline_with_debug(false, false).parse(&mut emitter);
        emitter
            .into_result()
            .expect("baseline pipeline must be valid");
        assert!(!baseline.debug_trace_scheduler_inputs);
        assert!(!baseline.debug_trace_tx_eval);
        let mut emitter = Emitter::new();
        let debug_enabled = pipeline_with_debug(true, true).parse(&mut emitter);
        emitter.into_result().expect("debug pipeline must be valid");
        assert!(debug_enabled.debug_trace_scheduler_inputs);
        assert!(debug_enabled.debug_trace_tx_eval);
    }
}
/// Zero-knowledge configuration section.
///
/// This section holds local resource settings only: diagnostic trace workers,
/// queues, retries, polynomial-opening bounds and the FASTPQ prover
/// settings. Every validity-affecting ZK value of a chain (proof limits,
/// windows, registry caps, relation-selecting keys, verification gas) is the
/// committed `zk_validity_policy_v1` parameter, or the protocol default, never
/// this file and never an environment variable. A configuration that names
/// such a value fails to load with an unknown-parameter error.
#[derive(Debug, ReadConfig, Clone)]
pub struct Zk {
    #[config(nested)]
    /// Optional local diagnostic trace checking; never proof authority.
    pub trace: DiagnosticTrace,
    #[config(nested)]
    /// Bounds for the diagnostic native polynomial-opening endpoint.
    pub ipa_commitment: IpaCommitment,
    #[config(nested)]
    /// FASTPQ prover configuration.
    pub fastpq: Fastpq,
}
