/// Autonomous FASTPQ producer scheduling and source limits (node-local only).
#[derive(Debug, ReadConfig, Clone, Copy)]
pub struct FastpqProducer {
    /// Retry interval including idle final-tip recovery.
    #[config(default = "defaults::zk::fastpq::PRODUCER_POLL_INTERVAL.into()")]
    pub poll_interval_ms: DurationMs,
    /// Cooperative monotonic bound on one attempt.
    #[config(default = "defaults::zk::fastpq::PRODUCER_STEP_TIMEOUT.into()")]
    pub step_timeout_ms: DurationMs,
    /// Native prefix steps per attempt (1 through 64).
    #[config(default = "defaults::zk::fastpq::PRODUCER_MAX_NATIVE_STEPS")]
    pub max_native_steps: std::num::NonZeroU16,
    /// Maximum full source entries admitted before allocation.
    #[config(default = "defaults::zk::fastpq::PRODUCER_MAX_SOURCE_ENTRIES")]
    pub max_source_entries: std::num::NonZeroU32,
    /// Maximum nonempty complete-effect statements admitted before allocation.
    #[config(default = "defaults::zk::fastpq::PRODUCER_MAX_SOURCE_STATEMENTS")]
    pub max_source_statements: std::num::NonZeroU32,
}
impl FastpqProducer {
    fn parse(self) -> actual::FastpqProducer {
        assert!(
            !self.poll_interval_ms.get().is_zero(),
            "fastpq.producer.poll_interval_ms must be nonzero"
        );
        assert!(
            !self.step_timeout_ms.get().is_zero(),
            "fastpq.producer.step_timeout_ms must be nonzero"
        );
        assert!(
            self.max_native_steps.get() <= 64,
            "fastpq.producer.max_native_steps must not exceed 64"
        );
        actual::FastpqProducer {
            poll_interval: self.poll_interval_ms.get(),
            step_timeout: self.step_timeout_ms.get(),
            max_native_steps: self.max_native_steps,
            max_source_entries: self.max_source_entries,
            max_source_statements: self.max_source_statements,
        }
    }
}
#[cfg(test)]
mod fastpq_producer_policy_tests {
    use super::*;
    fn policy() -> FastpqProducer {
        FastpqProducer {
            poll_interval_ms: defaults::zk::fastpq::PRODUCER_POLL_INTERVAL.into(),
            step_timeout_ms: defaults::zk::fastpq::PRODUCER_STEP_TIMEOUT.into(),
            max_native_steps: defaults::zk::fastpq::PRODUCER_MAX_NATIVE_STEPS,
            max_source_entries: defaults::zk::fastpq::PRODUCER_MAX_SOURCE_ENTRIES,
            max_source_statements: defaults::zk::fastpq::PRODUCER_MAX_SOURCE_STATEMENTS,
        }
    }
    #[test]
    fn producer_policy_uses_finite_canonical_owner_bounds() {
        let actual = policy().parse();
        assert!(!actual.poll_interval.is_zero());
        assert!(!actual.step_timeout.is_zero());
        assert!(actual.max_native_steps.get() <= 64);
        assert_eq!(
            actual.max_source_entries,
            actual::FastpqProducer::default().max_source_entries
        );
    }
    #[test]
    fn producer_policy_rejects_unbounded_native_turns_and_zero_timers() {
        for field in [0, 1, 2] {
            let mut value = policy();
            match field {
                0 => value.poll_interval_ms = std::time::Duration::ZERO.into(),
                1 => value.step_timeout_ms = std::time::Duration::ZERO.into(),
                _ => value.max_native_steps = std::num::NonZeroU16::new(65).unwrap(),
            }
            assert!(std::panic::catch_unwind(|| value.parse()).is_err());
        }
    }
}

/// FASTPQ prover configuration (user view).
#[derive(Debug, ReadConfig, Clone)]
pub struct Fastpq {
    /// Autonomous source discovery and bounded proof dispatch.
    #[config(nested)]
    pub producer: FastpqProducer,
    /// Execution mode used when initialising the FASTPQ prover backend.
    #[config(
        env = "FASTPQ_EXECUTION_MODE",
        default = "defaults::zk::fastpq::EXECUTION_MODE.parse().unwrap()"
    )]
    pub execution_mode: FastpqExecutionMode,
    /// Poseidon pipeline override (defaults to the execution mode when unset).
    #[config(
        env = "FASTPQ_POSEIDON_MODE",
        default = "defaults::zk::fastpq::POSEIDON_MODE.parse().unwrap()"
    )]
    pub poseidon_mode: FastpqPoseidonMode,
    /// Maximum queued FASTPQ proof sidecar attachments.
    #[config(default = "defaults::zk::fastpq::PROOF_SIDECAR_QUEUE_CAP")]
    pub proof_sidecar_queue_cap: NonZeroUsize,
    /// Maximum encoded FASTPQ proof snapshot accepted for sidecar persistence.
    #[config(default = "defaults::zk::fastpq::PROOF_SIDECAR_MAX_BYTES")]
    pub proof_sidecar_max_bytes: Bytes,
    /// Maximum merge attempts for a FASTPQ proof snapshot while the pipeline sidecar is pending.
    #[config(default = "defaults::zk::fastpq::PROOF_SIDECAR_MAX_RETRIES")]
    pub proof_sidecar_max_retries: NonZeroUsize,
    /// Optional device-class label exported via telemetry (e.g., `apple-m4`, `xeon-rtx-sm80`).
    #[config(env = "FASTPQ_DEVICE_CLASS")]
    pub device_class: Option<String>,
    /// Optional chip-family label derived from benchmark metadata (e.g., `m4`, `xeon-icelake`).
    #[config(env = "FASTPQ_CHIP_FAMILY")]
    pub chip_family: Option<String>,
    /// Optional GPU kind label (e.g., `integrated`, `discrete`).
    #[config(env = "FASTPQ_GPU_KIND")]
    pub gpu_kind: Option<String>,
    /// Optional Metal queue fan-out override (1–4 queues).
    #[config(env = "FASTPQ_METAL_QUEUE_FANOUT")]
    pub metal_queue_fanout: Option<usize>,
    /// Optional Metal queue column threshold override (positive total columns).
    #[config(env = "FASTPQ_METAL_COLUMN_THRESHOLD")]
    pub metal_queue_column_threshold: Option<u32>,
    /// Optional cap on concurrent Metal command buffers (None = heuristic).
    #[config(env = "FASTPQ_METAL_MAX_IN_FLIGHT")]
    pub metal_max_in_flight: Option<usize>,
    /// Optional override for Metal threadgroup width (None = pipeline default).
    #[config(env = "FASTPQ_METAL_THREADGROUP")]
    pub metal_threadgroup_width: Option<u64>,
    /// Enable per-dispatch Metal tracing (developer diagnostic; defaults off).
    #[config(
        env = "FASTPQ_METAL_TRACE",
        default = "defaults::zk::fastpq::METAL_TRACE"
    )]
    pub metal_trace: bool,
    /// Emit verbose Metal device enumeration logs (developer diagnostic; defaults off).
    #[config(
        env = "FASTPQ_DEBUG_METAL_ENUM",
        default = "defaults::zk::fastpq::METAL_DEBUG_ENUM"
    )]
    pub metal_debug_enum: bool,
}
impl Fastpq {
    fn parse(self) -> actual::Fastpq {
        fn sanitize_label(value: Option<String>) -> Option<String> {
            value.and_then(|value| {
                let trimmed = value.trim();
                if trimmed.is_empty() {
                    None
                } else {
                    Some(trimmed.to_owned())
                }
            })
        }
        assert!(
            self.proof_sidecar_max_bytes.get() != 0,
            "fastpq.proof_sidecar_max_bytes must be greater than zero"
        );
        actual::Fastpq {
            producer: self.producer.parse(),
            execution_mode: self.execution_mode.into_actual(),
            poseidon_mode: self.poseidon_mode.into_actual(),
            proof_sidecar_queue_cap: self.proof_sidecar_queue_cap,
            proof_sidecar_max_bytes: self.proof_sidecar_max_bytes,
            proof_sidecar_max_retries: self.proof_sidecar_max_retries,
            device_class: sanitize_label(self.device_class),
            chip_family: sanitize_label(self.chip_family),
            gpu_kind: sanitize_label(self.gpu_kind),
            metal_queue_fanout: self.metal_queue_fanout.inspect(|value| {
                assert!(
                    (1..=4).contains(value),
                    "fastpq.metal_queue_fanout must be between 1 and 4 (received {value})"
                );
            }),
            metal_queue_column_threshold: self.metal_queue_column_threshold.inspect(|value| {
                assert!(
                    *value != 0,
                    "fastpq.metal_queue_column_threshold must be greater than zero"
                );
            }),
            metal_max_in_flight: self.metal_max_in_flight.inspect(|value| {
                assert!(
                    *value != 0,
                    "fastpq.metal_max_in_flight must be greater than zero"
                );
            }),
            metal_threadgroup_width: self.metal_threadgroup_width.inspect(|value| {
                assert!(
                    *value != 0,
                    "fastpq.metal_threadgroup_width must be greater than zero"
                );
            }),
            metal_trace: self.metal_trace,
            metal_debug_enum: self.metal_debug_enum,
        }
    }
}
