/// User-level configuration container for `TrustedPeerPop`.
#[derive(Debug, Clone, norito::JsonDeserialize)]
pub struct TrustedPeerPop {
    /// Public key of the peer
    pub public_key: iroha_crypto::PublicKey,
    /// `PoP` bytes as hex string (e.g., "0x...") or plain hex.
    pub pop_hex: String,
}
#[cfg(test)]
mod trusted_peers_pop_env_tests {
    use super::*;
    use std::{borrow::Cow, str::FromStr};
    const PUBLIC_KEY_HEX: &str = "ea01309060D021340617E9554CCBC2CF3CC3DB922A9BA323ABDF7C271FCC6EF69BE7A8DEBCA7D9E96C0F0089ABA22CDAADE4A2";
    #[test]
    fn trusted_peers_pop_from_env_parses_json() {
        let json = format!(r#"[{{"public_key":"{PUBLIC_KEY_HEX}","pop_hex":"deadbeef"}}]"#);
        let parsed =
            TrustedPeerPops::from_env_str(Cow::Owned(json)).expect("parse trusted_peers_pop env");
        assert_eq!(parsed.0.len(), 1);
        assert_eq!(
            parsed.0[0].public_key,
            iroha_crypto::PublicKey::from_str(PUBLIC_KEY_HEX).expect("public key")
        );
        assert_eq!(parsed.0[0].pop_hex, "deadbeef");
    }
}
impl Sumeragi {
    /// Validate the optional local-parameter overrides: every interval and `sync_batch` must be
    /// non-zero (the remaining §9.4 rules need the committee and chain parameters and are
    /// checked by the node at startup).
    #[expect(
        clippy::too_many_arguments,
        reason = "one argument per optional flat `[sumeragi]` local-parameter key"
    )]
    fn parse_local_overrides(
        view_timeout_base_ms: Option<DurationMs>,
        view_timeout_max_ms: Option<DurationMs>,
        start_level_cap: Option<u32>,
        start_level_decay_after: Option<u32>,
        rebroadcast_interval_ms: Option<DurationMs>,
        status_keepalive_ms: Option<DurationMs>,
        build_timeout_ms: Option<DurationMs>,
        fetch_retry_ms: Option<DurationMs>,
        sync_batch: Option<u16>,
        sync_retry_ms: Option<DurationMs>,
        sync_max_bytes: Option<u32>,
        max_observers: Option<u32>,
    ) -> core::result::Result<actual::SumeragiLocalOverrides, String> {
        let intervals = [
            ("view_timeout_base_ms", view_timeout_base_ms),
            ("view_timeout_max_ms", view_timeout_max_ms),
            ("rebroadcast_interval_ms", rebroadcast_interval_ms),
            ("status_keepalive_ms", status_keepalive_ms),
            ("build_timeout_ms", build_timeout_ms),
            ("fetch_retry_ms", fetch_retry_ms),
            ("sync_retry_ms", sync_retry_ms),
        ];
        let mut zero: Vec<&str> = intervals
            .iter()
            .filter(|(_, value)| value.is_some_and(|value| value.get().is_zero()))
            .map(|(name, _)| *name)
            .collect();
        if sync_batch == Some(0) {
            zero.push("sync_batch");
        }
        if !zero.is_empty() {
            return Err(format!(
                "sumeragi local-parameter overrides must be non-zero: {}",
                zero.join(", ")
            ));
        }
        Ok(actual::SumeragiLocalOverrides {
            t_base: view_timeout_base_ms.map(DurationMs::get),
            t_max: view_timeout_max_ms.map(DurationMs::get),
            start_cap: start_level_cap,
            decay_after: start_level_decay_after,
            rebroadcast_interval: rebroadcast_interval_ms.map(DurationMs::get),
            status_keepalive: status_keepalive_ms.map(DurationMs::get),
            build_timeout: build_timeout_ms.map(DurationMs::get),
            fetch_retry: fetch_retry_ms.map(DurationMs::get),
            sync_batch,
            sync_retry: sync_retry_ms.map(DurationMs::get),
            sync_max_bytes,
            max_observers,
        })
    }

    /// Resolve the safety-record directory and installation log (§7.4): explicit values are
    /// resolved relative to their configuration file, defaults are siblings of the Kura store
    /// directory. The records must live outside the Kura store (which is backed up, restored
    /// and, in test networks, recreated) and the installation log outside the records.
    fn parse_record_paths(
        records_dir: Option<WithOrigin<PathBuf>>,
        installation_log: Option<WithOrigin<PathBuf>>,
        kura_store_dir: &WithOrigin<PathBuf>,
    ) -> core::result::Result<(PathBuf, PathBuf), String> {
        let store_dir = kura_store_dir.resolve_relative_path();
        let records_dir = match records_dir {
            Some(path) => path.resolve_relative_path(),
            None => actual::Sumeragi::default_records_dir(&store_dir).ok_or_else(|| {
                format!(
                    "sumeragi.records_dir has no default for kura.store_dir `{}` (no final path component); set it explicitly",
                    store_dir.display()
                )
            })?,
        };
        let installation_log = match installation_log {
            Some(path) => path.resolve_relative_path(),
            None => actual::Sumeragi::default_installation_log(&store_dir).ok_or_else(|| {
                format!(
                    "sumeragi.installation_log has no default for kura.store_dir `{}` (no final path component); set it explicitly",
                    store_dir.display()
                )
            })?,
        };
        if actual::path_is_within(&records_dir, &store_dir) {
            return Err(format!(
                "sumeragi.records_dir `{}` must not be inside kura.store_dir `{}`: safety records are never backed up or restored with the block store",
                records_dir.display(),
                store_dir.display()
            ));
        }
        if actual::path_is_within(&installation_log, &records_dir) {
            return Err(format!(
                "sumeragi.installation_log `{}` must be outside sumeragi.records_dir `{}`",
                installation_log.display(),
                records_dir.display()
            ));
        }
        Ok((records_dir, installation_log))
    }

    fn parse(
        self,
        emitter: &mut Emitter<ParseError>,
        kura_store_dir: &WithOrigin<PathBuf>,
    ) -> Option<actual::Sumeragi> {
        let Self {
            role,
            global_beacon_partial_signer_provider_handle,
            global_beacon_partial_signer_provider_revision,
            global_beacon_partial_signer_provider_policy_digest_hex,
            keys,
            view_timeout_base_ms,
            view_timeout_max_ms,
            start_level_cap,
            start_level_decay_after,
            rebroadcast_interval_ms,
            status_keepalive_ms,
            build_timeout_ms,
            fetch_retry_ms,
            sync_batch,
            sync_retry_ms,
            sync_max_bytes,
            max_observers,
            records_dir,
            installation_log,
            retired_keys,
        } = self;
        let mut valid = true;
        let local = match Self::parse_local_overrides(
            view_timeout_base_ms,
            view_timeout_max_ms,
            start_level_cap,
            start_level_decay_after,
            rebroadcast_interval_ms,
            status_keepalive_ms,
            build_timeout_ms,
            fetch_retry_ms,
            sync_batch,
            sync_retry_ms,
            sync_max_bytes,
            max_observers,
        ) {
            Ok(local) => local,
            Err(message) => {
                emitter.emit(Report::new(ParseError::InvalidSumeragiConfig).attach(message));
                valid = false;
                actual::SumeragiLocalOverrides::default()
            }
        };
        let record_paths =
            match Self::parse_record_paths(records_dir, installation_log, kura_store_dir) {
                Ok(paths) => Some(paths),
                Err(message) => {
                    emitter.emit(Report::new(ParseError::InvalidSumeragiConfig).attach(message));
                    valid = false;
                    None
                }
            };
        let mut unique_retired = BTreeSet::new();
        for key in &retired_keys {
            if !unique_retired.insert(key) {
                emitter.emit(
                    Report::new(ParseError::InvalidSumeragiConfig)
                        .attach(format!("sumeragi.retired_keys lists {key} more than once")),
                );
                valid = false;
            }
        }
        let global_beacon_partial_signer_provider_policy_digest =
            match validate_consensus_signer_provider_binding_v1(
                global_beacon_partial_signer_provider_handle.as_deref(),
                global_beacon_partial_signer_provider_revision,
                global_beacon_partial_signer_provider_policy_digest_hex.as_deref(),
            ) {
                Ok(policy_digest) => policy_digest,
                Err(reason) => {
                    emitter.emit(
                        Report::new(ParseError::InvalidSumeragiConfig).attach(format!(
                            "sumeragi global beacon partial signer binding is invalid: {reason}"
                        )),
                    );
                    valid = false;
                    None
                }
            };
        if global_beacon_partial_signer_provider_handle.is_some() && role != NodeRole::Validator {
            emitter.emit(
                Report::new(ParseError::InvalidSumeragiConfig).attach(
                    "an observer must not configure a global beacon partial signer provider",
                ),
            );
            valid = false;
        }
        let key_algorithms: BTreeSet<Algorithm> = keys.allowed_algorithms.iter().copied().collect();
        if !key_algorithms.contains(&Algorithm::BlsNormal) {
            emitter.emit(
                Report::new(ParseError::InvalidSumeragiConfig)
                    .attach("sumeragi.keys.allowed_algorithms must include BlsNormal"),
            );
            valid = false;
        }
        if !valid {
            return None;
        }
        let (records_dir, installation_log) = record_paths?;
        Some(actual::Sumeragi {
            local,
            records_dir,
            installation_log,
            retired_keys,
            role: match role {
                NodeRole::Validator => actual::NodeRole::Validator,
                NodeRole::Observer => actual::NodeRole::Observer,
            },
            global_beacon_partial_signer_provider_handle,
            global_beacon_partial_signer_provider_revision,
            global_beacon_partial_signer_provider_policy_digest,
            keys: actual::SumeragiKeys {
                activation_lead_blocks: keys.activation_lead_blocks,
                overlap_grace_blocks: keys.overlap_grace_blocks,
                expiry_grace_blocks: keys.expiry_grace_blocks,
                allowed_algorithms: key_algorithms,
            },
        })
    }
}
#[cfg(test)]
mod sumeragi_core_parse_tests {
    use super::*;
    use std::time::Duration;

    fn ms(value: u64) -> DurationMs {
        DurationMs(Duration::from_millis(value))
    }

    #[test]
    fn local_overrides_map_every_field() {
        let local = Sumeragi::parse_local_overrides(
            Some(ms(1)),
            Some(ms(2)),
            Some(3),
            Some(4),
            Some(ms(5)),
            Some(ms(6)),
            Some(ms(7)),
            Some(ms(8)),
            Some(9),
            Some(ms(10)),
            Some(11),
            Some(12),
        )
        .expect("non-zero overrides");
        assert_eq!(local.t_base, Some(Duration::from_millis(1)));
        assert_eq!(local.t_max, Some(Duration::from_millis(2)));
        assert_eq!(local.start_cap, Some(3));
        assert_eq!(local.decay_after, Some(4));
        assert_eq!(local.rebroadcast_interval, Some(Duration::from_millis(5)));
        assert_eq!(local.status_keepalive, Some(Duration::from_millis(6)));
        assert_eq!(local.build_timeout, Some(Duration::from_millis(7)));
        assert_eq!(local.fetch_retry, Some(Duration::from_millis(8)));
        assert_eq!(local.sync_batch, Some(9));
        assert_eq!(local.sync_retry, Some(Duration::from_millis(10)));
        assert_eq!(local.sync_max_bytes, Some(11));
        assert_eq!(local.max_observers, Some(12));
        let none = Sumeragi::parse_local_overrides(
            None, None, None, None, None, None, None, None, None, None, None, None,
        )
        .expect("no overrides");
        assert!(none.is_empty());
    }

    #[test]
    fn local_overrides_name_every_zero_interval() {
        let error = Sumeragi::parse_local_overrides(
            Some(ms(0)),
            None,
            Some(0),
            Some(0),
            None,
            None,
            Some(ms(0)),
            None,
            Some(0),
            None,
            Some(0),
            Some(0),
        )
        .expect_err("zero intervals");
        assert_eq!(
            error,
            "sumeragi local-parameter overrides must be non-zero: view_timeout_base_ms, build_timeout_ms, sync_batch"
        );
    }

    #[test]
    fn record_paths_default_to_store_siblings_and_reject_nesting() {
        let store = WithOrigin::inline(PathBuf::from("/data/kura"));
        let (records, log) =
            Sumeragi::parse_record_paths(None, None, &store).expect("default record paths");
        assert_eq!(records, PathBuf::from("/data/kura-sumeragi-records"));
        assert_eq!(log, PathBuf::from("/data/kura-sumeragi-installation.log"));

        let inside = Sumeragi::parse_record_paths(
            Some(WithOrigin::inline(PathBuf::from("/data/kura/records"))),
            None,
            &store,
        )
        .expect_err("records inside the store");
        assert!(
            inside.contains("must not be inside kura.store_dir"),
            "{inside}"
        );

        let nested_log = Sumeragi::parse_record_paths(
            Some(WithOrigin::inline(PathBuf::from("/srv/records"))),
            Some(WithOrigin::inline(PathBuf::from("/srv/records/log"))),
            &store,
        )
        .expect_err("log inside the records");
        assert!(
            nested_log.contains("must be outside sumeragi.records_dir"),
            "{nested_log}"
        );

        let rootless = WithOrigin::inline(PathBuf::from("/"));
        let no_default = Sumeragi::parse_record_paths(None, None, &rootless)
            .expect_err("no default for a store without a final component");
        assert!(
            no_default.contains("sumeragi.records_dir has no default"),
            "{no_default}"
        );
        let explicit = Sumeragi::parse_record_paths(
            Some(WithOrigin::inline(PathBuf::from("/records"))),
            None,
            &rootless,
        )
        .expect_err("records inside `/` and no log default");
        assert!(
            explicit.contains("installation_log has no default"),
            "{explicit}"
        );
    }
}
/// `SoraNet` handshake configuration (user view).
#[derive(Debug, Clone, ReadConfig)]
pub struct SoranetHandshake {
    #[config(default = "Self::default_descriptor_commit()")]
    descriptor_commit: WithOrigin<HexBytes>,
    #[config(default = "Self::default_client_capabilities()")]
    client_capabilities: WithOrigin<HexBytes>,
    #[config(default = "Self::default_relay_capabilities()")]
    relay_capabilities: WithOrigin<HexBytes>,
    #[config(default = "Self::default_trust_gossip()")]
    trust_gossip: bool,
    #[config(default = "Self::default_kem_id()")]
    kem_id: u8,
    /// Optional textual override for the ML-KEM suite (takes precedence over `kem_id`).
    kem_suite: Option<WithOrigin<MlKemSuiteParam>>,
    #[config(default = "Self::default_sig_id()")]
    sig_id: u8,
    resume_hash: Option<WithOrigin<HexBytes>>,
    #[config(nested)]
    pow: SoranetHandshakePow,
}
impl SoranetHandshake {
    const fn default_kem_id() -> u8 {
        1
    }
    const fn default_sig_id() -> u8 {
        1
    }
    fn default_descriptor_commit() -> HexBytes {
        HexBytes(DEFAULT_DESCRIPTOR_COMMIT.to_vec())
    }
    fn default_client_capabilities() -> HexBytes {
        HexBytes(DEFAULT_CLIENT_CAPABILITIES.to_vec())
    }
    fn default_relay_capabilities() -> HexBytes {
        HexBytes(DEFAULT_RELAY_CAPABILITIES.to_vec())
    }
    const fn default_trust_gossip() -> bool {
        true
    }
    fn synchronize_default_capabilities(
        descriptor_commit: &[u8],
        kem_id: u8,
        client_uses_defaults: bool,
        relay_uses_defaults: bool,
        client_capabilities: &mut [u8],
        relay_capabilities: &mut [u8],
    ) {
        // Keep the bundled fixture vectors aligned with simple top-level
        // overrides. Origin and exact-match checks ensure operator-supplied
        // vectors remain authoritative and are validated strictly by P2P.
        if client_uses_defaults {
            // First TLV: snnet.pqkem. Replace the preferred KEM and retain the
            // remaining canonical fallback list from the default vector.
            client_capabilities[4] = kem_id;
        }
        if relay_uses_defaults {
            relay_capabilities[4] = kem_id;
            // Third relay TLV: snnet.transcript_commit. Avoid slicing when an
            // invalid descriptor length is configured; startup validation will
            // then report the malformed field without panicking in the parser.
            if descriptor_commit.len() == DEFAULT_DESCRIPTOR_COMMIT.len() {
                relay_capabilities[16..48].copy_from_slice(descriptor_commit);
            }
        }
    }
    fn parse(self, emitter: &mut Emitter<ParseError>) -> actual::SoranetHandshake {
        let Self {
            descriptor_commit,
            client_capabilities,
            relay_capabilities,
            trust_gossip,
            kem_id,
            kem_suite,
            sig_id,
            resume_hash,
            pow,
        } = self;
        let resolved_suite = kem_suite.map_or_else(
            || {
                MlKemSuite::from_kem_id(kem_id).unwrap_or_else(|| {
                    emitter.emit(
                        Report::new(ParseError::InvalidSoranetHandshakeConfig).attach(format!(
                            "network.soranet_handshake.kem_id {kem_id} is unsupported"
                        )),
                    );
                    STREAMING_DEFAULT_KEM_SUITE
                })
            },
            |with_origin| with_origin.into_value().into_suite(),
        );
        let resolved_kem_id = resolved_suite.kem_id();
        let resolved_sig_id = if sig_id == 1 {
            sig_id
        } else {
            emitter.emit(
                Report::new(ParseError::InvalidSoranetHandshakeConfig).attach(format!(
                    "network.soranet_handshake.sig_id {sig_id} is unsupported"
                )),
            );
            1
        };
        let client_uses_defaults = matches!(
            client_capabilities.origin(),
            ParameterOrigin::Default { .. }
        ) && client_capabilities.value().0.as_slice()
            == DEFAULT_CLIENT_CAPABILITIES;
        let relay_uses_defaults =
            matches!(relay_capabilities.origin(), ParameterOrigin::Default { .. })
                && relay_capabilities.value().0.as_slice() == DEFAULT_RELAY_CAPABILITIES;
        let descriptor_commit = descriptor_commit.map(Vec::<u8>::from);
        let mut client_capabilities = client_capabilities.map(Vec::<u8>::from);
        let mut relay_capabilities = relay_capabilities.map(Vec::<u8>::from);
        Self::synchronize_default_capabilities(
            descriptor_commit.value(),
            resolved_kem_id,
            client_uses_defaults,
            relay_uses_defaults,
            client_capabilities.value_mut(),
            relay_capabilities.value_mut(),
        );
        actual::SoranetHandshake {
            descriptor_commit,
            client_capabilities,
            relay_capabilities,
            trust_gossip,
            kem_id: resolved_kem_id,
            sig_id: resolved_sig_id,
            resume_hash: resume_hash.map(|value| value.map(Vec::<u8>::from)),
            pow: pow.parse(emitter),
        }
    }
}
#[cfg(test)]
mod accel_tests {
    use super::*;
    use iroha_config_base::{read::ConfigReader, toml::TomlSource};

    #[test]
    fn omitted_acceleration_fields_supply_enabled_finite_process_defaults() {
        let parsed = ConfigReader::new()
            .with_toml_source(TomlSource::inline(toml::Table::new()))
            .read_and_complete::<Acceleration>()
            .unwrap()
            .parse();
        assert!(parsed.enable_simd && parsed.enable_metal && parsed.enable_cuda);
        assert_eq!(
            parsed.resource_limits,
            iroha_accel::RegistryLimits::STANDARD
        );
        assert_eq!(parsed.max_gpus, None);
        assert_eq!(parsed.merkle_min_leaves_metal, None);
        assert_eq!(parsed.merkle_min_leaves_cuda, None);
    }

    #[test]
    fn explicit_zero_limits_and_thresholds_are_preserved() {
        let table = toml::toml! {
            max_gpus = 0
            merkle_min_leaves_gpu = 0
            merkle_min_leaves_metal = 0
            merkle_min_leaves_cuda = 0
            prefer_cpu_sha2_max_leaves_aarch64 = 0
            prefer_cpu_sha2_max_leaves_x86 = 0
            [resource_limits]
            host_bytes = 0
            pinned_bytes = 0
            device_bytes = 0
            in_flight = 0
            metadata_bytes = 0
            observed_devices = 0
            discovery_ordinals = 0
            modules = 0
            streams = 0
            artifact_bytes = 0
        };
        let parsed = ConfigReader::new()
            .with_toml_source(TomlSource::inline(table))
            .read_and_complete::<Acceleration>()
            .unwrap()
            .parse();
        assert_eq!(parsed.max_gpus, Some(0));
        assert_eq!(parsed.merkle_min_leaves_gpu, 0);
        assert_eq!(parsed.merkle_min_leaves_metal, Some(0));
        assert_eq!(parsed.merkle_min_leaves_cuda, Some(0));
        assert_eq!(parsed.prefer_cpu_sha2_max_leaves_aarch64, Some(0));
        assert_eq!(parsed.prefer_cpu_sha2_max_leaves_x86, Some(0));
        assert_eq!(
            parsed.resource_limits,
            iroha_accel::RegistryLimits {
                metadata_bytes: 0,
                devices: 0,
                discovery_ordinals: 0,
                modules: 0,
                streams: 0,
                artifact_bytes: 0,
                work: iroha_accel::GpuResourceLimits {
                    host_bytes: 0,
                    pinned_bytes: 0,
                    device_bytes: 0,
                    in_flight: 0
                },
            }
        );
    }

    #[test]
    fn acceleration_resource_counts_reject_negative_and_oversized_geometry() {
        for table in [
            toml::toml! { [resource_limits] host_bytes = -1 },
            toml::toml! { [resource_limits] discovery_ordinals = 4_294_967_296_i64 },
            toml::toml! { max_gpus = -1 },
        ] {
            assert!(
                ConfigReader::new()
                    .with_toml_source(TomlSource::inline(table))
                    .read_and_complete::<Acceleration>()
                    .is_err()
            );
        }
    }
    #[test]
    fn accel_parse_respects_enable_simd_flag() {
        let user = Acceleration {
            resource_limits: AccelerationResourceLimits {
                host_bytes: defaults::accel::HOST_BYTES,
                pinned_bytes: defaults::accel::PINNED_BYTES,
                device_bytes: defaults::accel::DEVICE_BYTES,
                in_flight: defaults::accel::IN_FLIGHT,
                metadata_bytes: defaults::accel::METADATA_BYTES,
                observed_devices: defaults::accel::OBSERVED_DEVICES,
                discovery_ordinals: defaults::accel::DISCOVERY_ORDINALS,
                modules: defaults::accel::MODULES,
                streams: defaults::accel::STREAMS,
                artifact_bytes: defaults::accel::ARTIFACT_BYTES,
            },
            enable_simd: false,
            enable_cuda: true,
            enable_metal: true,
            max_gpus: None,
            merkle_min_leaves_gpu: defaults::accel::MERKLE_MIN_LEAVES_GPU,
            merkle_min_leaves_metal: None,
            merkle_min_leaves_cuda: None,
            prefer_cpu_sha2_max_leaves_aarch64: None,
            prefer_cpu_sha2_max_leaves_x86: None,
        };
        let actual = user.parse();
        assert!(!actual.enable_simd);
        assert!(actual.enable_cuda);
        assert_eq!(actual.max_gpus, None);
        assert_eq!(
            actual.merkle_min_leaves_gpu,
            defaults::accel::MERKLE_MIN_LEAVES_GPU
        );
    }
}
/// `PoW` admission settings supplied at the user configuration layer.
#[derive(Debug, Clone, ReadConfig)]
pub struct SoranetHandshakePow {
    #[config(default = "Self::default_difficulty()")]
    difficulty: NonZeroU16,
    #[config(default = "Self::default_max_future_skew()")]
    max_future_skew_secs: u64,
    #[config(default = "Self::default_min_ticket_ttl()")]
    min_ticket_ttl_secs: u64,
    #[config(default = "Self::default_ticket_ttl()")]
    ticket_ttl_secs: u64,
    #[config(default = "Self::default_puzzle_work_capacity()")]
    outbound_mint_capacity: NonZeroUsize,
    #[config(default = "Self::default_puzzle_work_capacity()")]
    inbound_verify_capacity: NonZeroUsize,
    #[config(default = "Self::default_revocation_store_capacity()")]
    revocation_store_capacity: u64,
    #[config(default = "Self::default_revocation_store_ttl()")]
    revocation_store_ttl_secs: u64,
    #[config(default = "Self::default_revocation_store_path()")]
    revocation_store_path: PathBuf,
    #[config(nested)]
    puzzle: SoranetHandshakePuzzle,
}
impl SoranetHandshakePow {
    const fn default_difficulty() -> NonZeroU16 {
        NonZeroU16::new(iroha_crypto::soranet::puzzle::DEFAULT_DIFFICULTY as u16)
            .expect("the canonical SoraNet difficulty is non-zero")
    }
    const fn default_max_future_skew() -> u64 {
        300
    }
    const fn default_min_ticket_ttl() -> u64 {
        30
    }
    const fn default_ticket_ttl() -> u64 {
        Self::default_max_future_skew()
    }
    const fn default_puzzle_work_capacity() -> NonZeroUsize {
        actual::SoranetPow::DEFAULT_PUZZLE_WORK_CAPACITY_PER_DIRECTION
    }
    const fn default_revocation_store_capacity() -> u64 {
        8_192
    }
    const fn default_revocation_store_ttl() -> u64 {
        900
    }
    fn default_revocation_store_path() -> PathBuf {
        PathBuf::from("./storage/soranet/ticket_revocations.norito")
    }
    fn parse(self, emitter: &mut Emitter<ParseError>) -> actual::SoranetPow {
        let Self {
            difficulty,
            max_future_skew_secs,
            min_ticket_ttl_secs,
            ticket_ttl_secs,
            outbound_mint_capacity,
            inbound_verify_capacity,
            revocation_store_capacity,
            revocation_store_ttl_secs,
            revocation_store_path,
            puzzle,
        } = self;
        let emit = |emitter: &mut Emitter<ParseError>, message: String| {
            emitter.emit(Report::new(ParseError::InvalidSoranetHandshakeConfig).attach(message));
        };
        let defaults = actual::SoranetPow::default_const();

        let configured_difficulty = difficulty.get();
        let difficulty = if configured_difficulty
            <= u16::from(iroha_crypto::soranet::puzzle::MAX_DIFFICULTY)
        {
            u8::try_from(configured_difficulty)
                .expect("validated SoraNet puzzle difficulty fits in u8")
        } else {
            emit(
                emitter,
                format!(
                    "network.soranet_handshake.pow.difficulty {configured_difficulty} exceeds the supported maximum {}",
                    iroha_crypto::soranet::puzzle::MAX_DIFFICULTY
                ),
            );
            defaults.difficulty
        };

        let mut ticket_timing_valid = if min_ticket_ttl_secs == 0 {
            emit(
                emitter,
                "network.soranet_handshake.pow.min_ticket_ttl_secs must be greater than zero"
                    .to_owned(),
            );
            false
        } else {
            true
        };
        ticket_timing_valid &= if max_future_skew_secs <= min_ticket_ttl_secs {
            emit(
                emitter,
                format!(
                    "network.soranet_handshake.pow.max_future_skew_secs {max_future_skew_secs} must exceed min_ticket_ttl_secs {min_ticket_ttl_secs}"
                ),
            );
            false
        } else {
            true
        };
        if ticket_ttl_secs <= min_ticket_ttl_secs {
            emit(
                emitter,
                format!(
                    "network.soranet_handshake.pow.ticket_ttl_secs {ticket_ttl_secs} must exceed min_ticket_ttl_secs {min_ticket_ttl_secs}"
                ),
            );
            ticket_timing_valid = false;
        }
        if ticket_ttl_secs > max_future_skew_secs {
            emit(
                emitter,
                format!(
                    "network.soranet_handshake.pow.ticket_ttl_secs {ticket_ttl_secs} must not exceed max_future_skew_secs {max_future_skew_secs}"
                ),
            );
            ticket_timing_valid = false;
        }
        let (max_future_skew, min_ticket_ttl, ticket_ttl) = if ticket_timing_valid {
            (
                Duration::from_secs(max_future_skew_secs),
                Duration::from_secs(min_ticket_ttl_secs),
                Duration::from_secs(ticket_ttl_secs),
            )
        } else {
            (
                defaults.max_future_skew,
                defaults.min_ticket_ttl,
                defaults.ticket_ttl,
            )
        };

        let validate_work_capacity =
            |name: &str, capacity: NonZeroUsize, emitter: &mut Emitter<ParseError>| {
                if capacity.get() <= actual::SoranetPow::MAX_PUZZLE_WORK_CAPACITY_PER_DIRECTION {
                    capacity
                } else {
                    emit(
                        emitter,
                        format!(
                            "network.soranet_handshake.pow.{name} {} exceeds the supported maximum {}",
                            capacity,
                            actual::SoranetPow::MAX_PUZZLE_WORK_CAPACITY_PER_DIRECTION
                        ),
                    );
                    actual::SoranetPow::DEFAULT_PUZZLE_WORK_CAPACITY_PER_DIRECTION
                }
            };
        let outbound_mint_capacity =
            validate_work_capacity("outbound_mint_capacity", outbound_mint_capacity, emitter);
        let inbound_verify_capacity =
            validate_work_capacity("inbound_verify_capacity", inbound_verify_capacity, emitter);

        let revocation_capacity_limit =
            iroha_crypto::soranet::pow::TICKET_REVOCATION_STORE_MAX_ENTRIES_V1;
        let revocation_store_capacity = match usize::try_from(revocation_store_capacity) {
            Ok(capacity) if (1..=revocation_capacity_limit).contains(&capacity) => capacity,
            _ => {
                emit(
                    emitter,
                    format!(
                        "network.soranet_handshake.pow.revocation_store_capacity {revocation_store_capacity} must be in 1..={revocation_capacity_limit}"
                    ),
                );
                defaults.revocation_store_capacity
            }
        };
        let revocation_ttl_valid = if revocation_store_ttl_secs == 0 {
            emit(
                emitter,
                "network.soranet_handshake.pow.revocation_store_ttl_secs must be greater than zero"
                    .to_owned(),
            );
            false
        } else if revocation_store_ttl_secs < max_future_skew_secs {
            emit(
                emitter,
                format!(
                    "network.soranet_handshake.pow.revocation_store_ttl_secs {revocation_store_ttl_secs} must cover max_future_skew_secs {max_future_skew_secs}"
                ),
            );
            false
        } else {
            true
        };
        let revocation_max_ttl = if revocation_ttl_valid {
            Duration::from_secs(revocation_store_ttl_secs)
        } else {
            defaults.revocation_max_ttl
        };
        actual::SoranetPow {
            difficulty,
            max_future_skew,
            min_ticket_ttl,
            ticket_ttl,
            outbound_mint_capacity,
            inbound_verify_capacity,
            revocation_store_capacity,
            revocation_max_ttl,
            revocation_store_path: revocation_store_path.to_string_lossy().into_owned().into(),
            puzzle: puzzle.parse(emitter),
        }
    }
}
/// Puzzle configuration supplied at the user level.
#[derive(Debug, Clone, Copy, ReadConfig)]
pub struct SoranetHandshakePuzzle {
    #[config(default = "Self::default_memory_kib()")]
    memory_kib: u32,
    #[config(default = "Self::default_time_cost()")]
    time_cost: u32,
    #[config(default = "Self::default_lanes()")]
    lanes: u32,
}
impl SoranetHandshakePuzzle {
    const fn default_memory_kib() -> u32 {
        64 * 1024
    }
    const fn default_time_cost() -> u32 {
        2
    }
    const fn default_lanes() -> u32 {
        1
    }
    fn parse(self, emitter: &mut Emitter<ParseError>) -> actual::SoranetPuzzle {
        let Self {
            memory_kib,
            time_cost,
            lanes,
        } = self;
        let emit = |emitter: &mut Emitter<ParseError>, message: String| {
            emitter.emit(Report::new(ParseError::InvalidSoranetHandshakeConfig).attach(message));
        };
        let defaults = actual::SoranetPuzzle::default_const();
        let memory = if (iroha_crypto::soranet::puzzle::MIN_MEMORY_KIB
            ..=iroha_crypto::soranet::puzzle::MAX_MEMORY_KIB)
            .contains(&memory_kib)
        {
            NonZeroU32::new(memory_kib).expect("validated SoraNet puzzle memory is non-zero")
        } else {
            emit(
                emitter,
                format!(
                    "network.soranet_handshake.pow.puzzle.memory_kib {memory_kib} must be in {}..={}",
                    iroha_crypto::soranet::puzzle::MIN_MEMORY_KIB,
                    iroha_crypto::soranet::puzzle::MAX_MEMORY_KIB
                ),
            );
            defaults.memory_kib
        };
        let time_cost = if (1..=iroha_crypto::soranet::puzzle::MAX_TIME_COST).contains(&time_cost) {
            NonZeroU32::new(time_cost).expect("validated SoraNet puzzle time cost is non-zero")
        } else {
            emit(
                emitter,
                format!(
                    "network.soranet_handshake.pow.puzzle.time_cost {time_cost} must be in 1..={}",
                    iroha_crypto::soranet::puzzle::MAX_TIME_COST
                ),
            );
            defaults.time_cost
        };
        let lanes = if (1..=iroha_crypto::soranet::puzzle::MAX_LANES).contains(&lanes) {
            NonZeroU32::new(lanes).expect("validated SoraNet puzzle lanes are non-zero")
        } else {
            emit(
                emitter,
                format!(
                    "network.soranet_handshake.pow.puzzle.lanes {lanes} must be in 1..={}",
                    iroha_crypto::soranet::puzzle::MAX_LANES
                ),
            );
            defaults.lanes
        };
        actual::SoranetPuzzle {
            memory_kib: memory,
            time_cost,
            lanes,
        }
    }
}
