/// User-level configuration container for Nexus storage budgets.
#[derive(Debug, Clone, Copy, ReadConfig, norito::JsonDeserialize)]
pub struct NexusStorage {
    /// Aggregate on-disk storage budget for Nexus nodes (bytes).
    ///
    /// When omitted, `irohad` derives a filesystem-aware budget at runtime without modifying the
    /// operator configuration.
    pub local_budget_bytes: Option<Bytes>,
    /// Block interval between disk budget enforcement scans (0 = every block).
    #[config(default = "defaults::nexus::storage::BUDGET_ENFORCE_INTERVAL_BLOCKS")]
    pub budget_enforce_interval_blocks: u64,
    /// WSV hot-tier deterministic encoded-key plus measured-value budget (bytes).
    #[config(default = "defaults::nexus::storage::MAX_WSV_MEMORY_BYTES")]
    pub max_wsv_memory_bytes: Bytes,
    /// Finite shared carrier-shell and descriptor pool, excluding nested payload allocations.
    /// Zero is a closed pool, never an unlimited setting.
    #[config(default = "defaults::nexus::storage::RETAINED_CARRIER_SHELL_BYTES")]
    pub retained_carrier_shell_bytes: usize,
    /// Finite process-local pool for committed-evidence preparation. At least one
    /// maximum prune-key and pending-penalty backing plan must fit.
    #[config(default = "defaults::nexus::storage::CONSENSUS_EVIDENCE_PREPARATION_BYTES")]
    pub consensus_evidence_preparation_bytes: usize,
    /// Finite process-local pool for flat consensus stake-index share keys.
    /// A capacity refusal remains a local retry, not an invalid block.
    #[config(default = "defaults::nexus::storage::CONSENSUS_STAKE_INDEX_BYTES")]
    pub consensus_stake_index_bytes: usize,
    /// Budget weights for dividing the disk cap across subsystems.
    #[config(nested)]
    pub disk_budget_weights: NexusStorageWeights,
}
impl_default!(NexusStorage {
    local_budget_bytes: None,
    budget_enforce_interval_blocks: defaults::nexus::storage::BUDGET_ENFORCE_INTERVAL_BLOCKS,
    max_wsv_memory_bytes: defaults::nexus::storage::MAX_WSV_MEMORY_BYTES,
    retained_carrier_shell_bytes: defaults::nexus::storage::RETAINED_CARRIER_SHELL_BYTES,
    consensus_evidence_preparation_bytes:
        defaults::nexus::storage::CONSENSUS_EVIDENCE_PREPARATION_BYTES,
    consensus_stake_index_bytes: defaults::nexus::storage::CONSENSUS_STAKE_INDEX_BYTES,
    disk_budget_weights: NexusStorageWeights::default(),
});
impl NexusStorage {
    fn parse(self, emitter: &mut Emitter<ParseError>) -> Option<actual::NexusStorage> {
        let weights = self.disk_budget_weights.parse(emitter)?;
        if self
            .local_budget_bytes
            .is_some_and(|budget| budget.get() == 0)
        {
            emitter.emit(Report::new(ParseError::InvalidNexusConfig).attach(
                "nexus.storage.local_budget_bytes must be greater than zero when configured",
            ));
            return None;
        }
        if self.consensus_evidence_preparation_bytes
            < defaults::nexus::storage::CONSENSUS_EVIDENCE_ONE_PLAN_BYTES
        {
            emitter.emit(Report::new(ParseError::InvalidNexusConfig).attach(format!(
                "nexus.storage.consensus_evidence_preparation_bytes must be at least {} bytes",
                defaults::nexus::storage::CONSENSUS_EVIDENCE_ONE_PLAN_BYTES
            )));
            return None;
        }
        if self.consensus_stake_index_bytes
            < defaults::nexus::storage::CONSENSUS_STAKE_INDEX_MIN_BYTES
        {
            emitter.emit(Report::new(ParseError::InvalidNexusConfig).attach(format!(
                "nexus.storage.consensus_stake_index_bytes must be at least {} bytes",
                defaults::nexus::storage::CONSENSUS_STAKE_INDEX_MIN_BYTES
            )));
            return None;
        }
        if let Some(local_budget_bytes) = self.local_budget_bytes {
            let total_bps = u64::from(defaults::nexus::storage::BPS_TOTAL);
            let minimum_budget_bytes = [
                weights.kura_blocks_bps,
                weights.wsv_snapshots_bps,
                weights.sorafs_bps,
            ]
            .into_iter()
            .map(|weight| {
                let weight = u64::from(weight);
                total_bps
                    .checked_add(weight - 1)
                    .expect("basis-point total is bounded")
                    / weight
            })
            .max()
            .expect("Nexus storage has a fixed non-empty component set");
            if local_budget_bytes.get() < minimum_budget_bytes {
                emitter.emit(Report::new(ParseError::InvalidNexusConfig).attach(format!(
                    "nexus.storage.local_budget_bytes must be at least {minimum_budget_bytes} bytes for every weighted component cap to remain non-zero"
                )));
                return None;
            }
        }
        let local_budget_bytes = self.local_budget_bytes;
        Some(actual::NexusStorage {
            local_budget_bytes,
            effective_local_budget_bytes: local_budget_bytes,
            budget_enforce_interval_blocks: self.budget_enforce_interval_blocks,
            max_wsv_memory_bytes: self.max_wsv_memory_bytes,
            retained_carrier_shell_bytes: self.retained_carrier_shell_bytes,
            consensus_evidence_preparation_bytes: self.consensus_evidence_preparation_bytes,
            consensus_stake_index_bytes: self.consensus_stake_index_bytes,
            disk_budget_weights: weights,
            configured_component_caps: None,
        })
    }
}
/// User-level configuration container for Nexus storage budget weights.
#[derive(Debug, Clone, Copy, ReadConfig, norito::JsonDeserialize)]
#[allow(clippy::struct_field_names)]
pub struct NexusStorageWeights {
    /// Budget share for Kura block storage (basis points).
    #[config(default = "defaults::nexus::storage::KURA_BLOCKS_BPS")]
    pub kura_blocks_bps: u16,
    /// Budget share for tiered-state cold snapshots (basis points).
    #[config(default = "defaults::nexus::storage::WSV_SNAPSHOTS_BPS")]
    pub wsv_snapshots_bps: u16,
    /// Budget share for `SoraFS` storage (basis points).
    #[config(default = "defaults::nexus::storage::SORAFS_BPS")]
    pub sorafs_bps: u16,
}
impl_default!(NexusStorageWeights {
    kura_blocks_bps: defaults::nexus::storage::KURA_BLOCKS_BPS,
    wsv_snapshots_bps: defaults::nexus::storage::WSV_SNAPSHOTS_BPS,
    sorafs_bps: defaults::nexus::storage::SORAFS_BPS,
});
impl NexusStorageWeights {
    fn total_bps(self) -> u32 {
        u32::from(self.kura_blocks_bps)
            + u32::from(self.wsv_snapshots_bps)
            + u32::from(self.sorafs_bps)
    }
    fn parse(self, emitter: &mut Emitter<ParseError>) -> Option<actual::NexusStorageWeights> {
        if let Some((field, _)) = [
            ("kura_blocks_bps", self.kura_blocks_bps),
            ("wsv_snapshots_bps", self.wsv_snapshots_bps),
            ("sorafs_bps", self.sorafs_bps),
        ]
        .into_iter()
        .find(|(_, weight)| *weight == 0)
        {
            emitter.emit(Report::new(ParseError::InvalidNexusConfig).attach(format!(
                "nexus.storage.disk_budget_weights entries must all be greater than zero; `{field}` is zero"
            )));
            return None;
        }
        let total = self.total_bps();
        if total != u32::from(defaults::nexus::storage::BPS_TOTAL) {
            emitter.emit(Report::new(ParseError::InvalidNexusConfig).attach(format!(
                "nexus.storage.disk_budget_weights must sum to {} bps (got {total})",
                defaults::nexus::storage::BPS_TOTAL
            )));
            return None;
        }
        Some(actual::NexusStorageWeights {
            kura_blocks_bps: self.kura_blocks_bps,
            wsv_snapshots_bps: self.wsv_snapshots_bps,
            sorafs_bps: self.sorafs_bps,
        })
    }
}
