/// User-level configuration container for `Snapshot`.
#[derive(Debug, Clone, ReadConfig)]
pub struct Snapshot {
    /// Snapshot operating mode.
    #[config(default, env = "SNAPSHOT_MODE")]
    pub mode: SnapshotMode,
    /// Interval between automatic snapshot creation events.
    #[config(default = "defaults::snapshot::CREATE_EVERY.into()")]
    pub create_every_ms: DurationMs,
    /// Directory where snapshot artifacts are stored.
    #[config(
        default = "PathBuf::from(defaults::snapshot::STORE_DIR)",
        env = "SNAPSHOT_STORE_DIR"
    )]
    pub store_dir: WithOrigin<PathBuf>,
    /// Chunk size (bytes) used to derive Merkle proofs for snapshots.
    #[config(default = "defaults::snapshot::MERKLE_CHUNK_SIZE_BYTES")]
    pub merkle_chunk_size_bytes: NonZeroUsize,
    /// Maximum authenticated snapshot bytes buffered during startup; restoration may
    /// use additional transient memory beyond this on-disk bound.
    #[config(default = "defaults::snapshot::MAX_PAYLOAD_BYTES")]
    pub max_payload_bytes: NonZeroUsize,
    /// Aggregate requested bytes in authenticated snapshot payload read buffers.
    /// The shared pool covers their original allocations through physical free,
    /// including generation validation during publication and garbage collection.
    /// Typed State, parser scratch, sidecars and writer output are separate.
    #[config(default = "defaults::snapshot::MAX_READ_BUFFER_BYTES")]
    pub max_read_buffer_bytes: NonZeroUsize,
    /// Typed decode and transient-allocation budgets for snapshot restoration.
    #[config(nested)]
    pub resources: SnapshotResourcePolicy,
    /// Optional public key used to verify snapshot signatures (defaults to node identity key).
    pub verification_public_key: Option<PublicKey>,
    /// Optional private key used to sign snapshots (defaults to node identity key).
    pub signing_private_key: Option<PrivateKey>,
}
impl Snapshot {
    fn validate_read_buffer_budget(&self) -> core::result::Result<(), String> {
        if self.max_read_buffer_bytes < self.max_payload_bytes {
            return Err(
                "snapshot.max_read_buffer_bytes must admit snapshot.max_payload_bytes".to_owned(),
            );
        }
        if self.max_read_buffer_bytes > self.resources.max_transient_bytes {
            return Err(
                "snapshot.max_read_buffer_bytes must not exceed snapshot.resources.max_transient_bytes"
                    .to_owned(),
            );
        }
        Ok(())
    }
}
/// Strict typed-decoder and transient-allocation budgets for snapshot restoration.
#[derive(Debug, Clone, Copy, ReadConfig)]
#[expect(
    clippy::struct_field_names,
    reason = "public config keys share max_ prefix"
)]
pub struct SnapshotResourcePolicy {
    /// Maximum nesting depth admitted by the typed decoder.
    #[config(default = "defaults::snapshot::MAX_DECODE_DEPTH")]
    pub max_decode_depth: NonZeroUsize,
    /// Maximum aggregate collection items decoded from one payload.
    #[config(default = "defaults::snapshot::MAX_DECODE_ITEMS")]
    pub max_decode_items: NonZeroUsize,
    /// Maximum UTF-8 bytes admitted for any individual string.
    #[config(default = "defaults::snapshot::MAX_STRING_BYTES")]
    pub max_string_bytes: NonZeroUsize,
    /// Maximum bytes admitted for any individual binary blob.
    #[config(default = "defaults::snapshot::MAX_BLOB_BYTES")]
    pub max_blob_bytes: NonZeroUsize,
    /// Maximum transient bytes allocated while restoring typed state.
    #[config(default = "defaults::snapshot::MAX_TRANSIENT_BYTES")]
    pub max_transient_bytes: NonZeroUsize,
}
impl_default!(SnapshotResourcePolicy {
    max_decode_depth: defaults::snapshot::MAX_DECODE_DEPTH,
    max_decode_items: defaults::snapshot::MAX_DECODE_ITEMS,
    max_string_bytes: defaults::snapshot::MAX_STRING_BYTES,
    max_blob_bytes: defaults::snapshot::MAX_BLOB_BYTES,
    max_transient_bytes: defaults::snapshot::MAX_TRANSIENT_BYTES,
});
impl SnapshotResourcePolicy {
    /// Validate resource-budget relationships against the enclosing payload bound.
    ///
    /// Relationships stay fail-closed so values cannot exceed the authenticated
    /// payload or the total transient-allocation budget.
    fn validate(&self, max_payload_bytes: NonZeroUsize) -> core::result::Result<(), String> {
        if self.max_decode_depth.get() > norito::core::MAX_VALUE_NESTING_DEPTH {
            return Err(format!(
                "snapshot.resources.max_decode_depth must not exceed Norito's structural limit of {}",
                norito::core::MAX_VALUE_NESTING_DEPTH
            ));
        }
        if self.max_string_bytes > self.max_blob_bytes {
            return Err(
                "snapshot.resources.max_string_bytes must not exceed max_blob_bytes".to_owned(),
            );
        }
        if self.max_blob_bytes > max_payload_bytes {
            return Err(
                "snapshot.resources.max_blob_bytes must not exceed snapshot.max_payload_bytes"
                    .to_owned(),
            );
        }
        if self.max_blob_bytes > self.max_transient_bytes {
            return Err(
                "snapshot.resources.max_blob_bytes must not exceed max_transient_bytes".to_owned(),
            );
        }
        Ok(())
    }
}
/// User-level non-secret custody and private TLS listener settings for Musubi publication.
#[derive(Debug, Clone, ReadConfig)]
pub struct MusubiPublication {
    /// Optional complete original identity, credentials and finite pin spending selection.
    #[config(nested)]
    pub installation: MusubiPublicationInstallation,
    /// Parent directory for the independent durable journal, seed and clock owners.
    #[config(default = "PathBuf::from(defaults::musubi_publication::CUSTODY_ROOT)")]
    pub custody_root: WithOrigin<PathBuf>,
    /// Bind address for the injected private TLS listener.
    #[config(default = "defaults::musubi_publication::PRIVATE_TLS_BIND.to_owned()")]
    pub private_tls_bind: String,
    /// Maximum simultaneous private TLS requests and bounded request buffers.
    #[config(default = "defaults::musubi_publication::MAX_INFLIGHT_REQUESTS")]
    pub max_inflight_requests: u16,
    /// Lifetime operation capacity of the durable publication journal.
    #[config(default = "defaults::musubi_publication::JOURNAL_MAX_OPERATIONS")]
    pub journal_max_operations: u32,
    /// Unexpired authorization capacity of the durable publication journal.
    #[config(default = "defaults::musubi_publication::JOURNAL_MAX_AUTHORIZATIONS")]
    pub journal_max_authorizations: u32,
    /// Total durable response bytes, including in-flight terminal reservations.
    #[config(default = "defaults::musubi_publication::JOURNAL_MAX_TOTAL_RESPONSE_BYTES")]
    pub journal_max_total_response_bytes: u64,
    /// Maximum complete canonical journal snapshot size.
    #[config(default = "defaults::musubi_publication::JOURNAL_MAX_SNAPSHOT_BYTES")]
    pub journal_max_snapshot_bytes: u64,
    /// Maximum number of exact CAR seed records retained in local custody.
    #[config(default = "defaults::musubi_publication::MAX_SEED_RECORDS")]
    pub max_seed_records: u32,
    /// Maximum total bytes of exact CAR seed records retained in local custody.
    #[config(default = "defaults::musubi_publication::MAX_SEED_BYTES")]
    pub max_seed_bytes: u64,
    /// Maximum publisher-clock lead accepted by publication authorization.
    #[config(default = "defaults::musubi_publication::MAX_FUTURE_CLOCK_SKEW_MS")]
    pub max_future_clock_skew_ms: u64,
    /// Lifetime assigned to a broker-signed seed-ingress receipt.
    #[config(default = "defaults::musubi_publication::RECEIPT_LIFETIME_MS")]
    pub receipt_lifetime_ms: u64,
    /// Paid-pin tier: exactly `hot`, `warm`, or `cold`.
    #[config(default = "defaults::musubi_publication::PIN_STORAGE_CLASS.to_owned()")]
    pub pin_storage_class: String,
    /// Paid-pin lifetime after submission, in seconds; must exceed the ingest deadline.
    #[config(default = "defaults::musubi_publication::PIN_RETENTION_HORIZON_SECS")]
    pub pin_retention_horizon_secs: u64,
    /// Canonical I105 account or exactly `ingress_broker`; no signing key is stored here.
    #[config(default = "defaults::musubi_publication::PIN_TRANSACTION_AUTHORITY.to_owned()")]
    pub pin_transaction_authority: String,
}
impl MusubiPublication {
    fn parse(self, emitter: &mut Emitter<ParseError>) -> actual::MusubiPublication {
        let pin_storage_class = parse_storage_class(&self.pin_storage_class).unwrap_or_else(|_| {
            emitter.emit(
                Report::new(ParseError::InvalidMusubiPublicationConfig).attach(
                    "musubi_publication.pin_storage_class must be exactly hot, warm, or cold",
                ),
            );
            SorafsStorageClass::Hot
        });
        let pin_transaction_authority = if self.pin_transaction_authority
            == defaults::musubi_publication::PIN_TRANSACTION_AUTHORITY
        {
            actual::MusubiPinTransactionAuthority::IngressBroker
        } else {
            match AccountId::parse_encoded(&self.pin_transaction_authority) {
                Ok(account) if account.to_string() == self.pin_transaction_authority => {
                    actual::MusubiPinTransactionAuthority::Account(account)
                }
                Ok(_) | Err(_) => {
                    emitter.emit(
                            Report::new(ParseError::InvalidMusubiPublicationConfig).attach(
                                "musubi_publication.pin_transaction_authority must be ingress_broker or one canonical domainless I105 account",
                            ),
                        );
                    actual::MusubiPinTransactionAuthority::IngressBroker
                }
            }
        };
        let private_tls_bind: std::net::SocketAddr =
            self.private_tls_bind.parse().unwrap_or_else(|_| {
                emitter.emit(
                    Report::new(ParseError::InvalidMusubiPublicationConfig)
                        .attach("musubi_publication.private_tls_bind must be a socket address"),
                );
                defaults::musubi_publication::private_tls_bind()
            });
        if self.max_inflight_requests == 0 || self.max_inflight_requests > 4 {
            emitter.emit(
                Report::new(ParseError::InvalidMusubiPublicationConfig)
                    .attach("musubi_publication.max_inflight_requests must be within 1..=4"),
            );
        }
        if self.journal_max_operations == 0 || self.journal_max_operations > 1_000_000 {
            emitter.emit(
                Report::new(ParseError::InvalidMusubiPublicationConfig)
                    .attach("musubi_publication.journal_max_operations must be within 1..=1000000"),
            );
        }
        if self.journal_max_authorizations == 0 || self.journal_max_authorizations > 1_000_000 {
            emitter.emit(
                Report::new(ParseError::InvalidMusubiPublicationConfig).attach(
                    "musubi_publication.journal_max_authorizations must be within 1..=1000000",
                ),
            );
        }
        if !(16 * 1024 * 1024..=64 * 1024 * 1024).contains(&self.journal_max_total_response_bytes) {
            emitter.emit(
                Report::new(ParseError::InvalidMusubiPublicationConfig)
                    .attach("musubi_publication.journal_max_total_response_bytes must be within 16..=64 MiB"),
            );
        }
        if self.journal_max_snapshot_bytes
            < self
                .journal_max_total_response_bytes
                .saturating_add(256 * 1024)
            || self.journal_max_snapshot_bytes > 96 * 1024 * 1024
        {
            emitter.emit(
                Report::new(ParseError::InvalidMusubiPublicationConfig)
                    .attach("musubi_publication.journal_max_snapshot_bytes must cover response bytes plus 256 KiB and be at most 96 MiB"),
            );
        }
        if self.max_seed_records == 0 || self.max_seed_records > 1_024 {
            emitter.emit(
                Report::new(ParseError::InvalidMusubiPublicationConfig)
                    .attach("musubi_publication.max_seed_records must be within 1..=1024"),
            );
        }
        if self.max_seed_bytes == 0 || self.max_seed_bytes > 64 * 1024 * 1024 * 1024 {
            emitter.emit(
                Report::new(ParseError::InvalidMusubiPublicationConfig)
                    .attach("musubi_publication.max_seed_bytes must be within 1 byte..=64 GiB"),
            );
        }
        if self.max_future_clock_skew_ms > 30_000 {
            emitter.emit(
                Report::new(ParseError::InvalidMusubiPublicationConfig)
                    .attach("musubi_publication.max_future_clock_skew_ms must be at most 30000"),
            );
        }
        if self.receipt_lifetime_ms == 0 || self.receipt_lifetime_ms > 24 * 60 * 60 * 1_000 {
            emitter.emit(
                Report::new(ParseError::InvalidMusubiPublicationConfig)
                    .attach("musubi_publication.receipt_lifetime_ms must be within 1..=86400000"),
            );
        }
        if self.pin_retention_horizon_secs
            <= u64::from(
                iroha_data_model::sorafs::pin_registry::SORAFS_AUTO_REPLICATION_ORDER_INGEST_DEADLINE_SECS_V1,
            )
            || self.pin_retention_horizon_secs
                > defaults::musubi_publication::MAX_PIN_RETENTION_HORIZON_SECS
        {
            emitter.emit(
                Report::new(ParseError::InvalidMusubiPublicationConfig).attach(
                    "musubi_publication.pin_retention_horizon_secs must exceed the SoraFS ingest deadline and be at most 365 days",
                ),
            );
        }
        let installation = self.installation.parse(emitter);
        if installation.is_some() && private_tls_bind.port() == 0 {
            emitter.emit(
                Report::new(ParseError::InvalidMusubiPublicationConfig)
                    .attach("installed publication requires a nonzero TLS port"),
            );
        }
        actual::MusubiPublication {
            installation,
            custody_root: self.custody_root.resolve_relative_path(),
            private_tls_bind,
            max_inflight_requests: self.max_inflight_requests,
            journal_max_operations: self.journal_max_operations,
            journal_max_authorizations: self.journal_max_authorizations,
            journal_max_total_response_bytes: self.journal_max_total_response_bytes,
            journal_max_snapshot_bytes: self.journal_max_snapshot_bytes,
            max_seed_records: self.max_seed_records,
            max_seed_bytes: self.max_seed_bytes,
            max_future_clock_skew_ms: self.max_future_clock_skew_ms,
            receipt_lifetime_ms: self.receipt_lifetime_ms,
            pin_storage_class,
            pin_retention_horizon_secs: self.pin_retention_horizon_secs,
            pin_transaction_authority,
        }
    }
}
/// User-level configuration container for the embedded Soracloud runtime manager.
#[derive(Debug, Clone, ReadConfig)]
pub struct SoracloudRuntime {
    /// Enable fail-closed Soracloud production posture checks.
    #[config(default = "defaults::soracloud_runtime::PRODUCTION_MODE")]
    pub production_mode: bool,
    /// Root directory for node-local Soracloud runtime state.
    #[config(default = "PathBuf::from(defaults::soracloud_runtime::STATE_DIR)")]
    pub state_dir: WithOrigin<PathBuf>,
    /// Reconciliation cadence against authoritative world state (milliseconds).
    #[config(
        default = "DurationMs(std::time::Duration::from_millis(defaults::soracloud_runtime::RECONCILE_INTERVAL_MS))"
    )]
    pub reconcile_interval_ms: DurationMs,
    /// Maximum concurrent artifact hydration workers, independent of Inrou guest concurrency.
    #[config(default = "defaults::soracloud_runtime::HYDRATION_CONCURRENCY")]
    pub hydration_concurrency: NonZeroUsize,
    /// Maximum idle prepared IVM runtimes retained independently of hydration workers.
    #[config(default = "defaults::soracloud_runtime::PREPARED_RUNTIME_CACHE_CAPACITY")]
    pub prepared_runtime_cache_capacity: NonZeroUsize,
    /// Cache budgets for hydrated Soracloud artifacts.
    #[config(default)]
    pub cache_budgets: SoracloudRuntimeCacheBudgets,
    /// Mutable Inrou microVM hosting limits.
    #[config(default)]
    pub inrou: SoracloudRuntimeInrou,
    /// Runtime-originated transaction submission settings.
    #[config(default)]
    pub submission: SoracloudRuntimeSubmission,
    /// Outbound egress policy for embedded runtimes.
    #[config(default)]
    pub egress: SoracloudRuntimeEgress,
}
impl SoracloudRuntime {
    fn parse(self, emitter: &mut Emitter<ParseError>) -> actual::SoracloudRuntime {
        let production_mode = self.production_mode;
        let egress = self.egress.parse(emitter);
        let submission = self.submission.parse(production_mode, emitter);
        let reconcile_interval = self.reconcile_interval_ms.get();
        if reconcile_interval < MIN_TIMER_INTERVAL {
            emitter.emit(
                Report::new(ParseError::InvalidSoracloudConfig).attach(
                    "soracloud_runtime.reconcile_interval_ms must be at least the minimum timer interval",
                ),
            );
        }
        if self.hydration_concurrency.get() > defaults::soracloud_runtime::HYDRATION_CONCURRENCY_MAX
        {
            emitter.emit(
                Report::new(ParseError::InvalidSoracloudConfig).attach(format!(
                    "soracloud_runtime.hydration_concurrency must not exceed {}",
                    defaults::soracloud_runtime::HYDRATION_CONCURRENCY_MAX
                )),
            );
        }
        if self.prepared_runtime_cache_capacity.get()
            > defaults::soracloud_runtime::PREPARED_RUNTIME_CACHE_CAPACITY_MAX
        {
            emitter.emit(
                Report::new(ParseError::InvalidSoracloudConfig).attach(format!(
                    "soracloud_runtime.prepared_runtime_cache_capacity must not exceed {}",
                    defaults::soracloud_runtime::PREPARED_RUNTIME_CACHE_CAPACITY_MAX
                )),
            );
        }
        actual::SoracloudRuntime {
            production_mode,
            state_dir: self.state_dir.resolve_relative_path(),
            reconcile_interval,
            hydration_concurrency: self.hydration_concurrency,
            prepared_runtime_cache_capacity: self.prepared_runtime_cache_capacity,
            cache_budgets: self.cache_budgets.parse(),
            inrou: self.inrou.parse(emitter),
            submission,
            egress,
        }
    }
}
