/// `WebAuthn` configuration for operator authentication.
#[derive(Debug, ReadConfig, Clone, norito::JsonDeserialize)]
pub struct ToriiOperatorWebAuthn {
    /// Master enable switch for `WebAuthn`.
    #[config(default = "defaults::torii::operator_auth::webauthn::ENABLED")]
    pub enabled: bool,
    /// RP ID expected by `WebAuthn` clients (must be set when enabled).
    pub rp_id: Option<String>,
    /// RP display name for `WebAuthn` options.
    #[config(default = "defaults::torii::operator_auth::webauthn::rp_name()")]
    pub rp_name: String,
    /// Allowed `WebAuthn` origins.
    #[config(default = "defaults::torii::operator_auth::webauthn::origins()")]
    pub origins: Vec<String>,
    /// User id inserted into `WebAuthn` registration options.
    #[config(default = "defaults::torii::operator_auth::webauthn::user_id()")]
    pub user_id: String,
    /// User name inserted into `WebAuthn` registration options.
    #[config(default = "defaults::torii::operator_auth::webauthn::user_name()")]
    pub user_name: String,
    /// User display name inserted into `WebAuthn` registration options.
    #[config(default = "defaults::torii::operator_auth::webauthn::user_display_name()")]
    pub user_display_name: String,
    /// Challenge TTL for registration/assertion options (seconds).
    #[config(default = "defaults::torii::operator_auth::webauthn::CHALLENGE_TTL_SECS")]
    pub challenge_ttl_secs: u64,
    /// Session token TTL after successful assertion (seconds).
    #[config(default = "defaults::torii::operator_auth::webauthn::SESSION_TTL_SECS")]
    pub session_ttl_secs: u64,
    /// Require user verification during assertions.
    #[config(default = "defaults::torii::operator_auth::webauthn::REQUIRE_USER_VERIFICATION")]
    pub require_user_verification: bool,
    /// Allowed `WebAuthn` algorithms (COSE labels).
    #[config(default = "defaults::torii::operator_auth::webauthn::allowed_algorithms()")]
    pub allowed_algorithms: Vec<String>,
}
impl ToriiOperatorAuth {
    fn parse(self, emitter: &mut Emitter<ParseError>) -> actual::ToriiOperatorAuth {
        if self.ephemeral_state_capacity.get()
            > defaults::torii::operator_auth::MAX_EPHEMERAL_STATE_CAPACITY
        {
            emit_torii_config_error(
                emitter,
                format!(
                    "torii.operator_auth.ephemeral_state_capacity must not exceed {}",
                    defaults::torii::operator_auth::MAX_EPHEMERAL_STATE_CAPACITY
                ),
            );
        }
        if self.credential_capacity.get() > defaults::torii::operator_auth::MAX_CREDENTIAL_CAPACITY
        {
            emit_torii_config_error(
                emitter,
                format!(
                    "torii.operator_auth.credential_capacity must not exceed {}",
                    defaults::torii::operator_auth::MAX_CREDENTIAL_CAPACITY
                ),
            );
        }
        if self.tokens.len() > defaults::torii::operator_auth::MAX_BOOTSTRAP_TOKENS {
            emit_torii_config_error(
                emitter,
                format!(
                    "torii.operator_auth.tokens must not contain more than {} entries",
                    defaults::torii::operator_auth::MAX_BOOTSTRAP_TOKENS
                ),
            );
        }
        let mut unique_tokens = BTreeSet::new();
        for token in &self.tokens {
            let min = defaults::torii::operator_auth::BOOTSTRAP_TOKEN_MIN_BYTES;
            let max = defaults::torii::operator_auth::BOOTSTRAP_TOKEN_MAX_BYTES;
            if !(min..=max).contains(&token.len()) {
                emit_torii_config_error(
                    emitter,
                    format!("torii.operator_auth.tokens entries must contain {min}..={max} bytes"),
                );
            }
            if !token.bytes().all(|byte| (0x21..=0x7e).contains(&byte)) {
                emit_torii_config_error(
                    emitter,
                    "torii.operator_auth.tokens entries must use visible ASCII without whitespace",
                );
            }
            if !unique_tokens.insert(token) {
                emit_torii_config_error(
                    emitter,
                    "torii.operator_auth.tokens must not contain duplicates",
                );
            }
        }
        let rate_per_minute = self
            .rate_per_minute
            .or(super::defaults::torii::operator_auth::RATE_PER_MIN)
            .and_then(std::num::NonZeroU32::new);
        let burst = self
            .burst
            .or(super::defaults::torii::operator_auth::BURST)
            .and_then(std::num::NonZeroU32::new);
        let lockout_failures = std::num::NonZeroU32::new(self.lockout_failures);
        if self.lockout_window_secs == 0 {
            emit_torii_config_error(
                emitter,
                "torii.operator_auth.lockout_window_secs must be greater than zero",
            );
        }
        if self.lockout_duration_secs == 0 {
            emit_torii_config_error(
                emitter,
                "torii.operator_auth.lockout_duration_secs must be greater than zero",
            );
        }
        let lockout_window = Duration::from_secs(self.lockout_window_secs);
        let lockout_duration = Duration::from_secs(self.lockout_duration_secs);
        let webauthn = if self.enabled {
            self.webauthn.parse(emitter)
        } else {
            None
        };
        if self.enabled && webauthn.is_none() {
            emit_torii_config_error(
                emitter,
                "torii.operator_auth.webauthn must be valid and enabled when operator auth is enabled",
            );
        }
        actual::ToriiOperatorAuth {
            enabled: self.enabled,
            require_mtls: self.require_mtls,
            mtls_trusted_proxy_cidrs: self.mtls_trusted_proxy_cidrs,
            tokens: self.tokens,
            rate_per_minute,
            burst,
            ephemeral_state_capacity: self.ephemeral_state_capacity,
            credential_capacity: self.credential_capacity,
            lockout: actual::OperatorAuthLockout {
                failures: lockout_failures,
                window: lockout_window,
                duration: lockout_duration,
            },
            webauthn,
        }
    }
}
impl ToriiOperatorWebAuthn {
    fn parse(self, emitter: &mut Emitter<ParseError>) -> Option<actual::OperatorWebAuthnConfig> {
        if !self.enabled {
            return None;
        }
        let mut invalid = false;
        let rp_id = self.rp_id.unwrap_or_else(|| {
            invalid = true;
            emit_torii_config_error(
                emitter,
                "torii.operator_auth.webauthn.rp_id must be set when WebAuthn is enabled",
            );
            String::new()
        });
        if let Err(error) = validate_webauthn_rp_id_v1(&rp_id) {
            invalid = true;
            emit_torii_config_error(
                emitter,
                format!(
                    "torii.operator_auth.webauthn.rp_id must be a canonical V1 DNS relying-party id: {error:?}"
                ),
            );
        }
        if self.origins.is_empty() {
            invalid = true;
            emit_torii_config_error(
                emitter,
                "torii.operator_auth.webauthn.origins must not be empty",
            );
        }
        let mut unique_origins = BTreeSet::new();
        let origins = self
            .origins
            .into_iter()
            .filter_map(|origin| {
                if !unique_origins.insert(origin.clone()) {
                    invalid = true;
                    emit_torii_config_error(
                        emitter,
                        format!(
                            "torii.operator_auth.webauthn.origins contains duplicate origin `{origin}`"
                        ),
                    );
                    return None;
                }
                if let Err(error) = validate_webauthn_origin_v1(&origin, &rp_id) {
                    invalid = true;
                    emit_torii_config_error(
                        emitter,
                        format!(
                            "invalid torii.operator_auth.webauthn.origins entry `{origin}`: {error:?}"
                        ),
                    );
                    return None;
                }
                match url::Url::parse(&origin) {
                    Ok(origin) => Some(origin),
                    Err(error) => {
                        invalid = true;
                        emit_torii_config_error(
                            emitter,
                            format!(
                                "invalid torii.operator_auth.webauthn.origins entry `{origin}`: {error}"
                            ),
                        );
                        None
                    }
                }
            })
            .collect();
        let user_id = self.user_id.into_bytes();
        if user_id.is_empty() || user_id.len() > 64 {
            invalid = true;
            emit_torii_config_error(
                emitter,
                "torii.operator_auth.webauthn.user_id must be 1..=64 bytes",
            );
        }
        let algorithms = self
            .allowed_algorithms
            .into_iter()
            .filter_map(|label| match parse_operator_webauthn_algorithm(&label) {
                Ok(algorithm) => Some(algorithm),
                Err(message) => {
                    invalid = true;
                    emit_torii_config_error(emitter, message);
                    None
                }
            })
            .collect::<Vec<_>>();
        if algorithms.is_empty() {
            invalid = true;
            emit_torii_config_error(
                emitter,
                "torii.operator_auth.webauthn.allowed_algorithms must not be empty",
            );
        }
        if self.challenge_ttl_secs == 0 {
            invalid = true;
            emit_torii_config_error(
                emitter,
                "torii.operator_auth.webauthn.challenge_ttl_secs must be greater than zero",
            );
        }
        if self.session_ttl_secs == 0 {
            invalid = true;
            emit_torii_config_error(
                emitter,
                "torii.operator_auth.webauthn.session_ttl_secs must be greater than zero",
            );
        }
        if invalid {
            return None;
        }
        Some(actual::OperatorWebAuthnConfig {
            rp_id,
            rp_name: self.rp_name,
            origins,
            user_id,
            user_name: self.user_name,
            user_display_name: self.user_display_name,
            challenge_ttl: Duration::from_secs(self.challenge_ttl_secs),
            session_ttl: Duration::from_secs(self.session_ttl_secs),
            require_user_verification: self.require_user_verification,
            allowed_algorithms: algorithms,
        })
    }
}
#[cfg(test)]
mod torii_operator_webauthn_tests {
    use super::*;
    fn valid_config() -> ToriiOperatorWebAuthn {
        ToriiOperatorWebAuthn {
            enabled: true,
            rp_id: Some("review.example".to_owned()),
            rp_name: "Iroha operator".to_owned(),
            origins: vec![
                "https://review.example".to_owned(),
                "https://login.review.example:8443".to_owned(),
            ],
            user_id: "iroha-operator".to_owned(),
            user_name: "operator".to_owned(),
            user_display_name: "Iroha operator".to_owned(),
            challenge_ttl_secs: 60,
            session_ttl_secs: 300,
            require_user_verification: true,
            allowed_algorithms: vec!["es256".to_owned()],
        }
    }
    #[test]
    fn operator_webauthn_accepts_exact_rp_and_subdomain_origins() {
        let mut emitter = Emitter::new();
        let parsed = valid_config()
            .parse(&mut emitter)
            .expect("enabled WebAuthn policy");
        emitter
            .into_result()
            .expect("valid WebAuthn configuration must not emit errors");
        assert_eq!(parsed.rp_id, "review.example");
        assert_eq!(
            parsed.origins.iter().map(Url::as_str).collect::<Vec<_>>(),
            [
                "https://review.example/",
                "https://login.review.example:8443/"
            ]
        );
    }
    #[test]
    fn operator_webauthn_rejects_noncanonical_rp_ids_and_origins() {
        for rp_id in ["Review.example", "localhost", "127.0.0.1"] {
            let mut config = valid_config();
            config.rp_id = Some(rp_id.to_owned());
            let mut emitter = Emitter::new();
            assert!(config.parse(&mut emitter).is_none(), "{rp_id:?}");
            assert!(emitter.into_result().is_err(), "{rp_id:?}");
        }
        for origin in [
            "http://review.example",
            "https://operator:secret@review.example",
            "https://review.example/path",
            "https://review.example?challenge=1",
            "https://review.example#fragment",
            "https://review.example:443",
            "https://foreign.example",
        ] {
            let mut config = valid_config();
            config.origins = vec![origin.to_owned()];
            let mut emitter = Emitter::new();
            assert!(config.parse(&mut emitter).is_none(), "{origin:?}");
            assert!(emitter.into_result().is_err(), "{origin:?}");
        }
        let mut duplicate = valid_config();
        duplicate.origins = vec![
            "https://review.example".to_owned(),
            "https://review.example".to_owned(),
        ];
        let mut emitter = Emitter::new();
        assert!(duplicate.parse(&mut emitter).is_none());
        assert!(emitter.into_result().is_err());
    }
}
fn parse_attachment_sanitizer_mode(
    value: &str,
) -> core::result::Result<actual::AttachmentSanitizerMode, String> {
    match value {
        "in_process" => Ok(actual::AttachmentSanitizerMode::InProcess),
        "subprocess" => Ok(actual::AttachmentSanitizerMode::Subprocess),
        other => Err(format!(
            "invalid torii.attachments_sanitizer_mode `{other}`; expected `subprocess` or `in_process`"
        )),
    }
}
fn parse_operator_webauthn_algorithm(
    value: &str,
) -> core::result::Result<actual::OperatorWebAuthnAlgorithm, String> {
    match value {
        "es256" => Ok(actual::OperatorWebAuthnAlgorithm::Es256),
        "ed25519" => Ok(actual::OperatorWebAuthnAlgorithm::Ed25519),
        other => Err(format!(
            "invalid torii.operator_auth.webauthn.allowed_algorithms entry `{other}`; expected `es256` or `ed25519`"
        )),
    }
}
#[cfg(test)]
mod exact_torii_label_tests {
    use super::*;

    #[test]
    fn operator_and_sanitizer_labels_reject_aliases_and_normalization() {
        parse_attachment_sanitizer_mode("in_process").expect("canonical sanitizer");
        parse_operator_webauthn_algorithm("es256").expect("canonical algorithm");

        for invalid in ["inline", "inprocess", "external", "process", "IN_PROCESS"] {
            assert!(
                parse_attachment_sanitizer_mode(invalid).is_err(),
                "{invalid:?}"
            );
        }
        for invalid in ["p256", "eddsa", "ES256", " ed25519"] {
            assert!(
                parse_operator_webauthn_algorithm(invalid).is_err(),
                "{invalid:?}"
            );
        }
    }
}
