/// Native MCP endpoint configuration parameters.
#[derive(Debug, ReadConfig, Clone, norito::JsonDeserialize)]
pub struct ToriiMcp {
    /// Master enable switch for native `/v1/mcp`.
    #[config(default = "defaults::torii::mcp::ENABLED")]
    pub enabled: bool,
    /// Non-zero maximum accepted request payload size in bytes.
    #[config(default = "defaults::torii::mcp::MAX_REQUEST_BYTES")]
    pub max_request_bytes: usize,
    /// Non-zero maximum number of tools emitted in one `tools/list` response page.
    #[config(default = "defaults::torii::mcp::MAX_TOOLS_PER_LIST")]
    pub max_tools_per_list: usize,
    /// Non-zero maximum number of MCP tool dispatches executing concurrently.
    #[config(default = "defaults::torii::mcp::MAX_INFLIGHT_DISPATCHES")]
    pub max_inflight_dispatches: usize,
    /// MCP tool profile (`read_only`, `writer`, `operator`).
    #[config(default = "defaults::torii::mcp::PROFILE.to_string()")]
    pub profile: String,
    /// Expose operator-only routes in MCP tool discovery.
    #[config(default = "defaults::torii::mcp::EXPOSE_OPERATOR_ROUTES")]
    pub expose_operator_routes: bool,
    /// Additional allow-list prefixes for tool names (empty => profile-only).
    #[config(default = "defaults::torii::mcp::allow_tool_prefixes()")]
    pub allow_tool_prefixes: Vec<String>,
    /// Additional deny-list prefixes for tool names.
    #[config(default = "defaults::torii::mcp::deny_tool_prefixes()")]
    pub deny_tool_prefixes: Vec<String>,
    /// Optional steady-state MCP request budget (requests/minute).
    pub rate_per_minute: Option<u32>,
    /// Optional MCP burst budget.
    pub burst: Option<u32>,
}
impl ToriiMcp {
    fn parse(self, emitter: &mut Emitter<ParseError>) -> actual::ToriiMcp {
        let profile = actual::ToriiMcpProfile::parse(&self.profile).unwrap_or_else(|| {
            emit_torii_config_error(
                emitter,
                format!(
                    "torii.mcp.profile must be exactly `read_only`, `writer`, or `operator`, got `{}`",
                    self.profile
                ),
            );
            actual::ToriiMcpProfile::ReadOnly
        });
        if self.expose_operator_routes && profile != actual::ToriiMcpProfile::Operator {
            emit_torii_config_error(
                emitter,
                "torii.mcp.expose_operator_routes=true requires torii.mcp.profile=\"operator\"",
            );
        }
        let max_request_bytes = if self.max_request_bytes == 0 {
            emit_torii_config_error(
                emitter,
                "torii.mcp.max_request_bytes must be greater than zero",
            );
            defaults::torii::mcp::MAX_REQUEST_BYTES
        } else {
            self.max_request_bytes
        };
        let max_tools_per_list = if self.max_tools_per_list == 0 {
            emit_torii_config_error(
                emitter,
                "torii.mcp.max_tools_per_list must be greater than zero",
            );
            defaults::torii::mcp::MAX_TOOLS_PER_LIST
        } else {
            self.max_tools_per_list
        };
        let max_inflight_dispatches = NonZeroUsize::new(self.max_inflight_dispatches)
            .unwrap_or_else(|| {
                emit_torii_config_error(
                    emitter,
                    "torii.mcp.max_inflight_dispatches must be greater than zero",
                );
                NonZeroUsize::new(defaults::torii::mcp::MAX_INFLIGHT_DISPATCHES)
                    .expect("default MCP in-flight dispatch limit is non-zero")
            });
        actual::ToriiMcp {
            enabled: self.enabled,
            max_request_bytes,
            max_tools_per_list,
            max_inflight_dispatches,
            profile,
            expose_operator_routes: self.expose_operator_routes,
            allow_tool_prefixes: self.allow_tool_prefixes,
            deny_tool_prefixes: self.deny_tool_prefixes,
            rate_per_minute: self
                .rate_per_minute
                .or(defaults::torii::mcp::RATE_PER_MINUTE)
                .and_then(NonZeroU32::new),
            burst: self
                .burst
                .or(defaults::torii::mcp::BURST)
                .and_then(NonZeroU32::new),
        }
    }
}
#[cfg(test)]
mod exact_torii_transport_label_tests {
    use super::*;

    #[test]
    fn rpc_and_mcp_aliases_emit_errors_without_unwinding() {
        for stage in ["general", "general_availability", "GA", " ga"] {
            let mut transport = ToriiTransport::default();
            transport.norito_rpc.stage = stage.to_owned();
            let mut emitter = Emitter::new();
            let _ = transport.parse(&mut emitter);
            assert!(emitter.into_result().is_err(), "{stage:?}");
        }
        for profile in ["readonly", "read-only", "write", "ops", "OPERATOR"] {
            let mcp = ToriiMcp {
                profile: profile.to_owned(),
                ..ToriiMcp::default()
            };
            let mut emitter = Emitter::new();
            let _ = mcp.parse(&mut emitter);
            assert!(emitter.into_result().is_err(), "{profile:?}");
        }
    }

    #[test]
    fn mcp_zero_capacities_are_rejected_without_unwinding() {
        for field in [
            "max_request_bytes",
            "max_tools_per_list",
            "max_inflight_dispatches",
        ] {
            let mut mcp = ToriiMcp::default();
            match field {
                "max_request_bytes" => mcp.max_request_bytes = 0,
                "max_tools_per_list" => mcp.max_tools_per_list = 0,
                "max_inflight_dispatches" => mcp.max_inflight_dispatches = 0,
                _ => unreachable!("test enumerates every MCP capacity field"),
            }
            let mut emitter = Emitter::new();
            let _ = mcp.parse(&mut emitter);
            let error = emitter
                .into_result()
                .expect_err("zero MCP capacities must fail closed");
            assert!(format!("{error:?}").contains(field), "{field}: {error:?}");
        }
    }

    #[test]
    fn mcp_operator_routes_require_the_operator_profile() {
        for profile in ["read_only", "writer"] {
            let mcp = ToriiMcp {
                profile: profile.to_owned(),
                expose_operator_routes: true,
                ..ToriiMcp::default()
            };
            let mut emitter = Emitter::new();
            let _ = mcp.parse(&mut emitter);
            let error = emitter
                .into_result()
                .expect_err("operator MCP exposure must keep both configuration gates");
            assert!(
                format!("{error:?}").contains("expose_operator_routes"),
                "{profile}: {error:?}"
            );
        }

        let mcp = ToriiMcp {
            profile: "operator".to_owned(),
            expose_operator_routes: true,
            ..ToriiMcp::default()
        };
        let mut emitter = Emitter::new();
        let parsed = mcp.parse(&mut emitter);
        emitter
            .into_result()
            .expect("the explicit Torii-local operator double opt-in is valid");
        assert_eq!(parsed.profile, actual::ToriiMcpProfile::Operator);
        assert!(parsed.expose_operator_routes);
    }
}
/// CORS response-header policy for Torii.
#[derive(Debug, ReadConfig, Clone, norito::JsonDeserialize)]
pub struct ToriiCors {
    /// Enable CORS response headers.
    #[config(default = "defaults::torii::cors::ENABLED")]
    pub enabled: bool,
    /// Browser origins allowed to make cross-origin requests.
    #[config(default = "defaults::torii::cors::allowed_origins()")]
    pub allowed_origins: Vec<String>,
    /// HTTP methods allowed in CORS preflight responses.
    #[config(default = "defaults::torii::cors::allowed_methods()")]
    pub allowed_methods: Vec<String>,
    /// Request headers allowed in CORS preflight responses.
    #[config(default = "defaults::torii::cors::allowed_headers()")]
    pub allowed_headers: Vec<String>,
    /// Response headers exposed to browser clients.
    #[config(default = "defaults::torii::cors::exposed_headers()")]
    pub exposed_headers: Vec<String>,
    /// Maximum preflight cache age in seconds.
    #[config(default = "defaults::torii::cors::MAX_AGE_SECS")]
    pub max_age_secs: u64,
}
impl Default for ToriiCors {
    fn default() -> Self {
        Self {
            enabled: defaults::torii::cors::ENABLED,
            allowed_origins: defaults::torii::cors::allowed_origins(),
            allowed_methods: defaults::torii::cors::allowed_methods(),
            allowed_headers: defaults::torii::cors::allowed_headers(),
            exposed_headers: defaults::torii::cors::exposed_headers(),
            max_age_secs: defaults::torii::cors::MAX_AGE_SECS,
        }
    }
}
impl ToriiCors {
    fn parse(self, emitter: &mut Emitter<ParseError>) -> actual::ToriiCors {
        let allowed_origins = normalize_cors_values(self.allowed_origins);
        let allowed_methods = normalize_cors_methods(self.allowed_methods, emitter);
        let allowed_headers =
            normalize_cors_headers("torii.cors.allowed_headers", self.allowed_headers, emitter);
        let exposed_headers =
            normalize_cors_headers("torii.cors.exposed_headers", self.exposed_headers, emitter);
        if self.enabled {
            require_non_empty_cors_list("torii.cors.allowed_origins", &allowed_origins, emitter);
            require_non_empty_cors_list("torii.cors.allowed_methods", &allowed_methods, emitter);
            require_non_empty_cors_list("torii.cors.allowed_headers", &allowed_headers, emitter);
        }
        for origin in &allowed_origins {
            validate_cors_origin(origin, emitter);
        }
        actual::ToriiCors {
            enabled: self.enabled,
            allowed_origins,
            allowed_methods,
            allowed_headers,
            exposed_headers,
            max_age_secs: self.max_age_secs,
        }
    }
}
fn normalize_cors_values(values: Vec<String>) -> Vec<String> {
    values
        .into_iter()
        .map(|value| value.trim().to_owned())
        .filter(|value| !value.is_empty())
        .collect()
}
fn normalize_cors_methods(values: Vec<String>, emitter: &mut Emitter<ParseError>) -> Vec<String> {
    values
        .into_iter()
        .filter_map(|value| {
            let normalized = value.trim().to_ascii_uppercase();
            if normalized.is_empty() {
                return None;
            }
            if !matches!(
                normalized.as_str(),
                "GET" | "POST" | "PUT" | "PATCH" | "DELETE" | "OPTIONS" | "HEAD"
            ) {
                emit_torii_config_error(
                    emitter,
                    format!(
                        "invalid torii.cors.allowed_methods entry `{}`; expected a standard HTTP method",
                        value.trim()
                    ),
                );
            }
            Some(normalized)
        })
        .collect()
}
fn normalize_cors_headers(
    config_path: &str,
    values: Vec<String>,
    emitter: &mut Emitter<ParseError>,
) -> Vec<String> {
    values
        .into_iter()
        .filter_map(|value| {
            let normalized = value.trim().to_ascii_lowercase();
            if normalized.is_empty() {
                return None;
            }
            if !is_http_token(&normalized) {
                emit_torii_config_error(
                    emitter,
                    format!(
                        "invalid {config_path} entry `{}`; expected an HTTP header name",
                        value.trim()
                    ),
                );
            }
            Some(normalized)
        })
        .collect()
}
fn require_non_empty_cors_list(
    config_path: &str,
    values: &[String],
    emitter: &mut Emitter<ParseError>,
) {
    if values.is_empty() {
        emit_torii_config_error(
            emitter,
            format!("torii.cors.enabled=true requires at least one {config_path} entry"),
        );
    }
}
fn validate_cors_origin(origin: &str, emitter: &mut Emitter<ParseError>) {
    if origin == "*" {
        emit_torii_config_error(
            emitter,
            "invalid torii.cors.allowed_origins entry `*`; configure explicit origins",
        );
        return;
    }
    let parsed = match url::Url::parse(origin) {
        Ok(parsed) => parsed,
        Err(err) => {
            emit_torii_config_error(
                emitter,
                format!("invalid torii.cors.allowed_origins entry `{origin}`: {err}"),
            );
            return;
        }
    };
    if !matches!(parsed.scheme(), "http" | "https") || parsed.host_str().is_none() {
        emit_torii_config_error(
            emitter,
            format!(
                "invalid torii.cors.allowed_origins entry `{origin}`; expected http(s)://host[:port]"
            ),
        );
    }
    if parsed.origin().ascii_serialization() != origin {
        emit_torii_config_error(
            emitter,
            format!(
                "invalid torii.cors.allowed_origins entry `{origin}`; configure origins without paths, queries, fragments, or credentials"
            ),
        );
    }
}
fn is_http_token(value: &str) -> bool {
    !value.is_empty()
        && value.bytes().all(|byte| {
            byte.is_ascii_alphanumeric()
                || matches!(
                    byte,
                    b'!' | b'#'
                        | b'$'
                        | b'%'
                        | b'&'
                        | b'\''
                        | b'*'
                        | b'+'
                        | b'-'
                        | b'.'
                        | b'^'
                        | b'_'
                        | b'`'
                        | b'|'
                        | b'~'
                )
        })
}
fn emit_torii_config_error(emitter: &mut Emitter<ParseError>, message: impl Into<String>) {
    emitter.emit(Report::new(ParseError::InvalidToriiConfig).attach(message.into()));
}
fn validate_torii_api_tokens(config: &Torii, emitter: &mut Emitter<ParseError>) {
    let tokens = config.api_tokens.as_deref().unwrap_or_default();
    if config.require_api_token && tokens.is_empty() {
        emit_torii_config_error(
            emitter,
            "torii.require_api_token=true requires at least one torii.api_tokens entry",
        );
    }
    if !config.require_api_token && !tokens.is_empty() {
        emit_torii_config_error(
            emitter,
            "torii.api_tokens must be empty when torii.require_api_token=false",
        );
    }
    if tokens.len() > defaults::torii::API_TOKEN_MAX_COUNT_V1 {
        emit_torii_config_error(
            emitter,
            format!(
                "torii.api_tokens must not contain more than {} entries",
                defaults::torii::API_TOKEN_MAX_COUNT_V1
            ),
        );
    }
    let mut unique_tokens = BTreeSet::new();
    for token in tokens {
        let min = defaults::torii::API_TOKEN_MIN_BYTES_V1;
        let max = defaults::torii::API_TOKEN_MAX_BYTES_V1;
        if !(min..=max).contains(&token.len()) {
            emit_torii_config_error(
                emitter,
                format!("torii.api_tokens entries must contain {min}..={max} bytes"),
            );
        }
        if !token.bytes().all(|byte| (0x21..=0x7e).contains(&byte)) {
            emit_torii_config_error(
                emitter,
                "torii.api_tokens entries must use visible ASCII without whitespace",
            );
        }
        if !unique_tokens.insert(token) {
            emit_torii_config_error(emitter, "torii.api_tokens must not contain duplicates");
        }
    }
}
fn validate_app_api_limits(config: &Torii, emitter: &mut Emitter<ParseError>) {
    for (field, value) in [
        (
            "torii.app_api_default_list_limit",
            config.app_api_default_list_limit,
        ),
        (
            "torii.app_api_max_list_limit",
            config.app_api_max_list_limit,
        ),
        (
            "torii.app_api_max_fetch_size",
            config.app_api_max_fetch_size,
        ),
        (
            "torii.app_api_rate_limit_cost_per_page",
            config.app_api_rate_limit_cost_per_page,
        ),
    ] {
        if value == 0 {
            emit_torii_config_error(emitter, format!("{field} must be greater than zero"));
        }
    }
    if config.app_api_default_list_limit != 0
        && config.app_api_max_list_limit < config.app_api_default_list_limit
    {
        emit_torii_config_error(
            emitter,
            "torii.app_api_max_list_limit must be at least torii.app_api_default_list_limit",
        );
    }
    if config.app_api_default_list_limit != 0
        && config.app_api_max_fetch_size < config.app_api_default_list_limit
    {
        emit_torii_config_error(
            emitter,
            "torii.app_api_max_fetch_size must be at least torii.app_api_default_list_limit",
        );
    }
}
