/// Per-scheme concurrency limit for the Torii pre-auth gate.
#[derive(Debug, Clone, ReadConfig, norito::JsonDeserialize)]
pub struct PreauthSchemeLimit {
    /// Label of the connection scheme (matches `ConnScheme::label()` in Torii).
    pub scheme: String,
    /// Maximum concurrent pre-auth connections allowed for this scheme.
    pub max_connections: NonZeroUsize,
}
impl Connect {
    fn parse(self, emitter: &mut Emitter<ParseError>) -> actual::Connect {
        for (field, invalid) in [
            ("torii.connect.ws_max_sessions", self.ws_max_sessions == 0),
            (
                "torii.connect.session_ttl_ms",
                self.session_ttl_ms.get().is_zero(),
            ),
            ("torii.connect.frame_max_bytes", self.frame_max_bytes == 0),
            (
                "torii.connect.session_buffer_max_bytes",
                self.session_buffer_max_bytes == 0,
            ),
            (
                "torii.connect.ping_interval_ms",
                self.ping_interval_ms.get().is_zero(),
            ),
            (
                "torii.connect.ping_miss_tolerance",
                self.ping_miss_tolerance == 0,
            ),
            (
                "torii.connect.ping_min_interval_ms",
                self.ping_min_interval_ms.get().is_zero(),
            ),
            (
                "torii.connect.dedupe_ttl_ms",
                self.dedupe_ttl_ms.get().is_zero(),
            ),
            ("torii.connect.dedupe_cap", self.dedupe_cap == 0),
        ] {
            if invalid {
                emit_torii_config_error(emitter, format!("{field} must be greater than zero"));
            }
        }
        if self.ping_interval_ms.get() < self.ping_min_interval_ms.get() {
            emit_torii_config_error(
                emitter,
                "torii.connect.ping_interval_ms must be at least torii.connect.ping_min_interval_ms",
            );
        }
        actual::Connect {
            enabled: self.enabled,
            ws_max_sessions: self.ws_max_sessions,
            ws_per_ip_max_sessions: self.ws_per_ip_max_sessions,
            ws_rate_per_ip_per_min: self.ws_rate_per_ip_per_min,
            session_ttl: self.session_ttl_ms.get(),
            frame_max_bytes: self.frame_max_bytes,
            session_buffer_max_bytes: self.session_buffer_max_bytes,
            ping_interval: self.ping_interval_ms.get(),
            ping_miss_tolerance: self.ping_miss_tolerance,
            ping_min_interval: self.ping_min_interval_ms.get(),
            dedupe_ttl: self.dedupe_ttl_ms.get(),
            dedupe_cap: self.dedupe_cap,
            relay_enabled: self.relay_enabled,
            relay_strategy: match self.relay_strategy {
                ConnectRelayStrategy::Broadcast => actual::ConnectRelayStrategy::Broadcast,
                ConnectRelayStrategy::LocalOnly => actual::ConnectRelayStrategy::LocalOnly,
            },
            p2p_ttl_hops: self.p2p_ttl_hops,
        }
    }
}
