impl SorafsPopCredentialService {
    fn parse(
        self,
        storage_enabled: bool,
        emitter: &mut Emitter<ParseError>,
    ) -> Option<actual::SorafsPopCredentialService> {
        const MAX_COLLECTION: u32 = 65_536;
        const MAX_WORKER_INTERVAL_MS: u64 = 60 * 60 * 1_000;
        const MAX_FINALIZED_TIME_SKEW_SECS: u64 = 5 * 60;
        fn emit(emitter: &mut Emitter<ParseError>, message: impl Into<String>) {
            emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(message.into()));
        }
        fn clean_text(value: &str) -> bool {
            !value.is_empty()
                && value == value.trim()
                && value.len() <= 256
                && !value.chars().any(char::is_control)
        }
        fn parse_digest(
            emitter: &mut Emitter<ParseError>,
            path: &str,
            value: Option<&str>,
        ) -> Option<[u8; 32]> {
            let Some(value) = value else {
                emit(emitter, format!("{path} is required when enabled"));
                return None;
            };
            if value.len() != 64
                || !value
                    .bytes()
                    .all(|byte| matches!(byte, b'0'..=b'9' | b'a'..=b'f'))
            {
                emit(
                    emitter,
                    format!("{path} must be exactly 64 lowercase hexadecimal characters"),
                );
                return None;
            }
            let mut digest = [0_u8; 32];
            hex::decode_to_slice(value, &mut digest)
                .expect("validated lowercase 32-byte hexadecimal");
            if digest == [0; 32] {
                emit(emitter, format!("{path} must be nonzero"));
                return None;
            }
            Some(digest)
        }
        let authority_fields_present = self.issuer_policy_digest_hex.is_some()
            || self.issuer_id.is_some()
            || self.issuer_signer_handle.is_some()
            || self.issuer_public_key_hex.is_some()
            || self.enrollment_recipient_key_id.is_some()
            || self.enrollment_recipient_public_key_digest_hex.is_some()
            || self.wallet_recipient_key_id.is_some()
            || self.wallet_recipient_public_key_digest_hex.is_some()
            || self.wallet_wrapping_key_id.is_some()
            || self.runtime_provider_registry_handle.is_some()
            || self.runtime_provider_registry_revision.is_some()
            || self.runtime_provider_registry_policy_digest_hex.is_some()
            || !self.approval_signers.is_empty();
        if !self.enabled {
            if authority_fields_present {
                emit(
                    emitter,
                    "sorafs.storage.pop_credentials authority fields must be absent when disabled",
                );
            }
            return None;
        }
        if !storage_enabled {
            emit(
                emitter,
                "sorafs.storage.pop_credentials.enabled requires storage.enabled",
            );
        }
        if self.issuer_state_dir.as_os_str().is_empty()
            || self.wallet_state_dir.as_os_str().is_empty()
            || self.issuer_state_dir == self.wallet_state_dir
            || !self.issuer_state_dir.is_absolute()
            || !self.wallet_state_dir.is_absolute()
        {
            emit(
                emitter,
                "sorafs.storage.pop_credentials issuer_state_dir and wallet_state_dir must be distinct non-empty absolute paths",
            );
        }
        let issuer_policy_digest = parse_digest(
            emitter,
            "sorafs.storage.pop_credentials.issuer_policy_digest_hex",
            self.issuer_policy_digest_hex.as_deref(),
        );
        let issuer_public_key = parse_digest(
            emitter,
            "sorafs.storage.pop_credentials.issuer_public_key_hex",
            self.issuer_public_key_hex.as_deref(),
        );
        let enrollment_recipient_public_key_digest = parse_digest(
            emitter,
            "sorafs.storage.pop_credentials.enrollment_recipient_public_key_digest_hex",
            self.enrollment_recipient_public_key_digest_hex.as_deref(),
        );
        let wallet_recipient_public_key_digest = parse_digest(
            emitter,
            "sorafs.storage.pop_credentials.wallet_recipient_public_key_digest_hex",
            self.wallet_recipient_public_key_digest_hex.as_deref(),
        );
        let runtime_provider_registry_policy_digest = parse_digest(
            emitter,
            "sorafs.storage.pop_credentials.runtime_provider_registry_policy_digest_hex",
            self.runtime_provider_registry_policy_digest_hex.as_deref(),
        );
        let mut provider_handles_valid = true;
        for (path, value) in [
            (
                "sorafs.storage.pop_credentials.issuer_signer_handle",
                self.issuer_signer_handle.as_deref(),
            ),
            (
                "sorafs.storage.pop_credentials.enrollment_recipient_key_id",
                self.enrollment_recipient_key_id.as_deref(),
            ),
            (
                "sorafs.storage.pop_credentials.wallet_recipient_key_id",
                self.wallet_recipient_key_id.as_deref(),
            ),
            (
                "sorafs.storage.pop_credentials.wallet_wrapping_key_id",
                self.wallet_wrapping_key_id.as_deref(),
            ),
            (
                "sorafs.storage.pop_credentials.runtime_provider_registry_handle",
                self.runtime_provider_registry_handle.as_deref(),
            ),
        ] {
            match value {
                Some(value) if is_production_runtime_handle(value) => {}
                _ => {
                    provider_handles_valid = false;
                    emit(
                        emitter,
                        format!("{path} is required and must be a production runtime handle"),
                    );
                }
            }
        }
        match self.issuer_id.as_deref() {
            Some(value) if clean_text(value) => {}
            _ => emit(
                emitter,
                "sorafs.storage.pop_credentials.issuer_id is required and must be canonical bounded text",
            ),
        }
        let registry_revision_valid = self
            .runtime_provider_registry_revision
            .is_some_and(|revision| revision != 0);
        if !registry_revision_valid {
            emit(
                emitter,
                "sorafs.storage.pop_credentials.runtime_provider_registry_revision must be nonzero",
            );
        }
        if let Some(public_key) = issuer_public_key
            && PublicKey::from_bytes(Algorithm::Ed25519, &public_key).is_err()
        {
            emit(
                emitter,
                "sorafs.storage.pop_credentials.issuer_public_key_hex is not a valid Ed25519 public key",
            );
        }
        let mut approval_signers = Vec::with_capacity(self.approval_signers.len());
        let mut previous_signer_id: Option<&str> = None;
        let mut public_keys = BTreeSet::new();
        for (index, signer) in self.approval_signers.iter().enumerate() {
            if !clean_text(&signer.signer_id)
                || previous_signer_id.is_some_and(|previous| previous >= signer.signer_id.as_str())
            {
                emit(
                    emitter,
                    format!(
                        "sorafs.storage.pop_credentials.approval_signers[{index}].signer_id must be canonical and strictly ordered"
                    ),
                );
            }
            let public_key = parse_digest(
                emitter,
                &format!("sorafs.storage.pop_credentials.approval_signers[{index}].public_key_hex"),
                Some(&signer.public_key_hex),
            );
            if let Some(public_key) = public_key {
                if PublicKey::from_bytes(Algorithm::Ed25519, &public_key).is_err() {
                    emit(
                        emitter,
                        format!(
                            "sorafs.storage.pop_credentials.approval_signers[{index}].public_key_hex is not a valid Ed25519 public key"
                        ),
                    );
                }
                if !public_keys.insert(public_key) {
                    emit(
                        emitter,
                        "sorafs.storage.pop_credentials approval public keys must be distinct",
                    );
                }
                approval_signers.push(actual::SorafsPopApprovalSigner {
                    signer_id: signer.signer_id.clone(),
                    public_key,
                    revoked_at_epoch: signer.revoked_at_epoch,
                });
            }
            if signer.revoked_at_epoch == Some(0) {
                emit(
                    emitter,
                    format!(
                        "sorafs.storage.pop_credentials.approval_signers[{index}].revoked_at_epoch must be nonzero"
                    ),
                );
            }
            previous_signer_id = Some(&signer.signer_id);
        }
        if self.approval_quorum < 2 || usize::from(self.approval_quorum) > approval_signers.len() {
            emit(
                emitter,
                "sorafs.storage.pop_credentials.approval_quorum must require at least two and not exceed the governed signer count",
            );
        }
        for (field, value) in [
            ("max_pending_enrollments", self.max_pending_enrollments),
            ("max_outbox_entries", self.max_outbox_entries),
            ("max_dead_letters", self.max_dead_letters),
            ("max_seen_nullifiers", self.max_seen_nullifiers),
        ] {
            if value == 0 || value > MAX_COLLECTION {
                emit(
                    emitter,
                    format!(
                        "sorafs.storage.pop_credentials.{field} must be within 1..={MAX_COLLECTION}"
                    ),
                );
            }
        }
        if self.max_submission_attempts == 0 {
            emit(
                emitter,
                "sorafs.storage.pop_credentials.max_submission_attempts must be nonzero",
            );
        }
        if self.worker_interval_ms == 0 || self.worker_interval_ms > MAX_WORKER_INTERVAL_MS {
            emit(
                emitter,
                format!(
                    "sorafs.storage.pop_credentials.worker_interval_ms must be within 1..={MAX_WORKER_INTERVAL_MS}"
                ),
            );
        }
        if self.max_finalized_time_skew_secs > MAX_FINALIZED_TIME_SKEW_SECS {
            emit(
                emitter,
                format!(
                    "sorafs.storage.pop_credentials.max_finalized_time_skew_secs must be within 0..={MAX_FINALIZED_TIME_SKEW_SECS}"
                ),
            );
        }
        if !provider_handles_valid || !registry_revision_valid {
            return None;
        }
        Some(actual::SorafsPopCredentialService {
            issuer_state_dir: self.issuer_state_dir,
            wallet_state_dir: self.wallet_state_dir,
            issuer_policy_digest: issuer_policy_digest?,
            issuer_id: self.issuer_id?,
            issuer_signer_handle: self.issuer_signer_handle?,
            issuer_public_key: issuer_public_key?,
            enrollment_recipient_key_id: self.enrollment_recipient_key_id?,
            enrollment_recipient_public_key_digest: enrollment_recipient_public_key_digest?,
            wallet_recipient_key_id: self.wallet_recipient_key_id?,
            wallet_recipient_public_key_digest: wallet_recipient_public_key_digest?,
            wallet_wrapping_key_id: self.wallet_wrapping_key_id?,
            runtime_provider_registry_handle: self.runtime_provider_registry_handle?,
            runtime_provider_registry_revision: self.runtime_provider_registry_revision?,
            runtime_provider_registry_policy_digest: runtime_provider_registry_policy_digest?,
            approval_quorum: self.approval_quorum,
            approval_signers,
            max_pending_enrollments: self.max_pending_enrollments,
            max_outbox_entries: self.max_outbox_entries,
            max_dead_letters: self.max_dead_letters,
            max_seen_nullifiers: self.max_seen_nullifiers,
            max_submission_attempts: self.max_submission_attempts,
            worker_interval: Duration::from_millis(self.worker_interval_ms),
            max_finalized_time_skew: Duration::from_secs(self.max_finalized_time_skew_secs),
        })
    }
}
