fn parse_sorafs_gateway_runtime_provider_binding(
    emitter: &mut Emitter<ParseError>,
    parent_path: &str,
    field_prefix: &str,
    enabled: bool,
    provider_handle: Option<&str>,
    revision: Option<u64>,
    policy_digest_hex: Option<&str>,
) -> Option<actual::SorafsGatewayRuntimeProviderBinding> {
    let emit = |emitter: &mut Emitter<ParseError>, message: String| {
        emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(message));
    };
    let field_path = |suffix: &str| format!("{parent_path}.{field_prefix}_{suffix}");
    let any_configured =
        provider_handle.is_some() || revision.is_some() || policy_digest_hex.is_some();
    if !enabled {
        if any_configured {
            emit(
                emitter,
                format!("{parent_path}.{field_prefix} binding fields must be absent when disabled"),
            );
        }
        return None;
    }
    let provider_handle = match provider_handle {
        Some(value) if is_production_runtime_handle(value) => Some(value.to_owned()),
        Some(_) => {
            emit(
                emitter,
                format!(
                    "{} must be one canonical production provider handle",
                    field_path("handle")
                ),
            );
            None
        }
        None => {
            emit(
                emitter,
                format!("{} is required when enabled", field_path("handle")),
            );
            None
        }
    };
    let revision = match revision {
        Some(value) if value != 0 => Some(value),
        Some(_) => {
            emit(
                emitter,
                format!("{} must be nonzero", field_path("revision")),
            );
            None
        }
        None => {
            emit(
                emitter,
                format!("{} is required when enabled", field_path("revision")),
            );
            None
        }
    };
    let policy_digest = match policy_digest_hex {
        Some(value)
            if value.len() == 64
                && value
                    .bytes()
                    .all(|byte| matches!(byte, b'0'..=b'9' | b'a'..=b'f')) =>
        {
            let mut digest = [0_u8; 32];
            hex::decode_to_slice(value, &mut digest)
                .expect("validated lowercase 32-byte hexadecimal");
            if digest == [0; 32] {
                emit(
                    emitter,
                    format!("{} must be nonzero", field_path("policy_digest_hex")),
                );
                None
            } else {
                Some(digest)
            }
        }
        Some(_) => {
            emit(
                emitter,
                format!(
                    "{} must be exactly 64 lowercase hexadecimal characters",
                    field_path("policy_digest_hex")
                ),
            );
            None
        }
        None => {
            emit(
                emitter,
                format!(
                    "{} is required when enabled",
                    field_path("policy_digest_hex")
                ),
            );
            None
        }
    };
    Some(actual::SorafsGatewayRuntimeProviderBinding {
        provider_handle: provider_handle?,
        revision: revision?,
        policy_digest: policy_digest?,
    })
}
#[cfg(test)]
#[path = "user/sorafs_gateway_runtime_provider_binding_tests.rs"]
mod sorafs_gateway_runtime_provider_binding_tests;
fn is_canonical_nonzero_ed25519_public_key_hex(value: &str) -> bool {
    value.len() == 64
        && value
            .bytes()
            .all(|byte| matches!(byte, b'0'..=b'9' | b'a'..=b'f'))
        && value.bytes().any(|byte| byte != b'0')
}
fn is_canonical_strong_ed25519_public_key_hex(value: &str) -> bool {
    if !is_canonical_nonzero_ed25519_public_key_hex(value) {
        return false;
    }
    let bytes = hex::decode(value).expect("validated lowercase Ed25519 public key hex");
    let Ok(public_key) = PublicKey::from_bytes(Algorithm::Ed25519, &bytes) else {
        return false;
    };
    let (algorithm, canonical_bytes) = public_key.to_bytes();
    algorithm == Algorithm::Ed25519 && canonical_bytes == bytes.as_slice()
}
fn is_canonical_governance_dag_publisher_peer_id(value: &str) -> bool {
    !value.is_empty() && value.len() <= 128 && value.bytes().all(|byte| byte.is_ascii_graphic())
}
impl SorafsStorage {
    fn parse(
        self,
        repair_enabled: bool,
        emitter: &mut Emitter<ParseError>,
    ) -> actual::SorafsStorage {
        let storage_enabled = self.enabled;
        let reputation_runtime_enabled = self.reputation_runtime.enabled;
        let signed_local_governance_producer_configured = self.governance_dag_dir.is_some();
        let reserve_enabled = self.reserve_worker.enabled;
        let orderbook_enabled = self.orderbook_worker.enabled;
        let native_transaction_signers = self.native_transaction_signers.parse(
            SorafsNativeTransactionSignerEnablement {
                proof_outcome: storage_enabled,
                repair: storage_enabled || repair_enabled,
                reserve: storage_enabled || reserve_enabled,
                orderbook: storage_enabled || orderbook_enabled,
            },
            emitter,
        );
        let provider_id =
            self.provider_id_hex.as_deref().and_then(|raw| {
                if raw.len() != 64
                    || raw
                        .bytes()
                        .any(|byte| !byte.is_ascii_digit() && !(b'a'..=b'f').contains(&byte))
                {
                    emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(
                        "sorafs.storage.provider_id_hex must be 64 lowercase hex characters",
                    ));
                    return None;
                }
                let decoded = hex::decode(raw).expect("validated lowercase provider hex");
                let mut provider = [0_u8; 32];
                provider.copy_from_slice(&decoded);
                if provider == [0; 32] {
                    emitter.emit(
                        Report::new(ParseError::InvalidSorafsConfig)
                            .attach("sorafs.storage.provider_id_hex must be nonzero"),
                    );
                    return None;
                }
                Some(ProviderId::new(provider))
            });
        if self.pdp_sample_window == 0
            || self.pdp_sample_window > defaults::sorafs::storage::PDP_SAMPLE_WINDOW_MAX
        {
            emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(format!(
                "sorafs.storage.pdp_sample_window must be within 1..={}, got {}",
                defaults::sorafs::storage::PDP_SAMPLE_WINDOW_MAX,
                self.pdp_sample_window
            )));
        }
        if self.pdp_tree_memory_limit_bytes.0 == 0 {
            emitter
                .emit(Report::new(ParseError::InvalidSorafsConfig).attach(
                    "sorafs.storage.pdp_tree_memory_limit_bytes must be greater than zero",
                ));
        }
        let moderation_screening_authority_bundle_digest =
            self.moderation_screening_authority_bundle_digest_hex
                .as_deref()
                .and_then(|raw| {
                    if raw.len() != 64
                        || raw.bytes().any(|byte| {
                            !byte.is_ascii_digit() && !(b'a'..=b'f').contains(&byte)
                        })
                    {
                        emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(
                            "sorafs.storage.moderation_screening_authority_bundle_digest_hex must be 64 lowercase hex characters",
                        ));
                        return None;
                    }
                    let decoded = hex::decode(raw).expect("validated lowercase hex");
                    let mut digest = [0_u8; 32];
                    digest.copy_from_slice(&decoded);
                    if digest.iter().all(|byte| *byte == 0) {
                        emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(
                            "sorafs.storage.moderation_screening_authority_bundle_digest_hex must be nonzero",
                        ));
                        return None;
                    }
                    Some(digest)
                });
        let moderation_quarantine_key_provider_fields = [
            self.moderation_quarantine_key_provider_handle.is_some(),
            self.moderation_quarantine_key_provider_revision.is_some(),
            self.moderation_quarantine_key_provider_policy_digest_hex
                .is_some(),
        ];
        let moderation_quarantine_key_provider = if moderation_quarantine_key_provider_fields
            .iter()
            .any(|present| *present)
        {
            if moderation_quarantine_key_provider_fields
                .iter()
                .all(|present| *present)
            {
                let handle = self
                    .moderation_quarantine_key_provider_handle
                    .as_deref()
                    .expect("all moderation quarantine-key fields checked above");
                let revision = self
                    .moderation_quarantine_key_provider_revision
                    .expect("all moderation quarantine-key fields checked above");
                let digest_hex = self
                    .moderation_quarantine_key_provider_policy_digest_hex
                    .as_deref()
                    .expect("all moderation quarantine-key fields checked above");
                let handle_valid = is_production_runtime_handle(handle);
                if !handle_valid {
                    emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(
                            "sorafs.storage.moderation_quarantine_key_provider_handle must be a production opaque handle",
                        ));
                }
                if revision == 0 {
                    emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(
                            "sorafs.storage.moderation_quarantine_key_provider_revision must be nonzero",
                        ));
                }
                let policy_digest = if digest_hex.len() == 64
                    && digest_hex
                        .bytes()
                        .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
                {
                    let decoded =
                        hex::decode(digest_hex).expect("validated lowercase policy digest hex");
                    let mut digest = [0_u8; 32];
                    digest.copy_from_slice(&decoded);
                    if digest == [0; 32] {
                        emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(
                                "sorafs.storage.moderation_quarantine_key_provider_policy_digest_hex must be nonzero",
                            ));
                        None
                    } else {
                        Some(digest)
                    }
                } else {
                    emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(
                            "sorafs.storage.moderation_quarantine_key_provider_policy_digest_hex must be canonical lowercase non-zero 32-byte hex",
                        ));
                    None
                };
                if handle_valid && revision != 0 {
                    policy_digest.map(|policy_digest| {
                        actual::SorafsModerationQuarantineKeyProviderBinding {
                            handle: handle.to_owned(),
                            revision,
                            policy_digest,
                        }
                    })
                } else {
                    None
                }
            } else {
                emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(
                        "sorafs.storage moderation quarantine-key provider handle, revision, and policy digest must be configured together",
                    ));
                None
            }
        } else {
            None
        };
        if moderation_quarantine_key_provider.is_some() && !self.enabled {
            emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(
                "sorafs.storage moderation quarantine-key provider binding requires storage.enabled",
            ));
        }
        if self.moderation_screening_enabled {
            if !self.enabled {
                emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(
                    "sorafs.storage.moderation_screening_enabled requires storage.enabled",
                ));
            }
            match self.moderation_screening_authority_bundle_path.as_deref() {
                None => {
                    emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(
                        "sorafs.storage.moderation_screening_authority_bundle_path is required when moderation screening is enabled",
                    ));
                }
                Some(path) if !path.is_absolute() => {
                    emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(
                        "sorafs.storage.moderation_screening_authority_bundle_path must be absolute",
                    ));
                }
                Some(_) => {}
            }
            if moderation_screening_authority_bundle_digest.is_none() {
                emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(
                    "sorafs.storage.moderation_screening_authority_bundle_digest_hex is required when moderation screening is enabled",
                ));
            }
            if moderation_quarantine_key_provider.is_none() {
                emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(
                    "sorafs.storage moderation screening requires an exact production quarantine-key provider handle, revision, and policy digest",
                ));
            }
        }
        if let Some(handle) = self.governance_dag_signer_handle.as_deref()
            && !is_production_runtime_handle(handle)
        {
            emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(
                "sorafs.storage.governance_dag_signer_handle must be a production runtime handle",
            ));
        }
        if self.governance_dag_signer_revision == Some(0) {
            emitter.emit(
                Report::new(ParseError::InvalidSorafsConfig)
                    .attach("sorafs.storage.governance_dag_signer_revision must be nonzero"),
            );
        }
        if let Some(peer_id) = self.governance_dag_publisher_peer_id.as_deref()
            && !is_canonical_governance_dag_publisher_peer_id(peer_id)
        {
            emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(
                "sorafs.storage.governance_dag_publisher_peer_id must be 1..=128 visible ASCII bytes",
            ));
        }
        let governance_dag_signer_policy_digest = self
            .governance_dag_signer_policy_digest_hex
            .as_deref()
            .and_then(|digest_hex| {
                if digest_hex.len() != 64
                    || !digest_hex
                        .bytes()
                        .all(|byte| matches!(byte, b'0'..=b'9' | b'a'..=b'f'))
                {
                    emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(
                        "sorafs.storage.governance_dag_signer_policy_digest_hex must be canonical lowercase non-zero 32-byte hex",
                    ));
                    return None;
                }
                let decoded =
                    hex::decode(digest_hex).expect("validated lowercase signer policy digest hex");
                let mut digest = [0_u8; 32];
                digest.copy_from_slice(&decoded);
                if digest == [0; 32] {
                    emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(
                        "sorafs.storage.governance_dag_signer_policy_digest_hex must be nonzero",
                    ));
                    return None;
                }
                Some(digest)
            });
        if let Some(public_key) = self.governance_dag_publisher_public_key_hex.as_deref()
            && !is_canonical_strong_ed25519_public_key_hex(public_key)
        {
            emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(
                "sorafs.storage.governance_dag_publisher_public_key_hex must be a canonical lowercase strong Ed25519 public key",
            ));
        }
        let runtime_signer_fields = [
            self.governance_dag_publisher_peer_id.is_some(),
            self.governance_dag_signer_handle.is_some(),
            self.governance_dag_signer_revision.is_some(),
            self.governance_dag_signer_policy_digest_hex.is_some(),
            self.governance_dag_publisher_public_key_hex.is_some(),
        ];
        let any_runtime_signer_field = runtime_signer_fields.iter().any(|present| *present);
        let complete_runtime_signer_binding = runtime_signer_fields.iter().all(|present| *present);
        if any_runtime_signer_field && !complete_runtime_signer_binding {
            emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(
                "sorafs.storage signed Governance DAG publication requires publisher peer id, signer handle, signer revision, signer policy digest, and publisher public key together",
            ));
        }
        if self.governance_dag_dir.is_some() && !any_runtime_signer_field {
            emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(
                "sorafs.storage.governance_dag_dir requires the complete signed Governance DAG publisher binding",
            ));
        }
        if self.governance_dag_dir.is_none() && any_runtime_signer_field {
            emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(
                "sorafs.storage signed Governance DAG publisher binding is forbidden without governance_dag_dir",
            ));
        }
        if self.governance_dag_dir.is_some() && complete_runtime_signer_binding && !self.enabled {
            emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(
                "sorafs.storage signed Governance DAG publication requires storage.enabled",
            ));
        }
        if self.privacy_aggregates.enabled {
            if self.governance_dag_dir.is_none() {
                emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(
                    "sorafs.storage.privacy_aggregates.enabled requires an explicit governance_dag_dir",
                ));
            }
            if !complete_runtime_signer_binding {
                emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(
                    "sorafs.storage.privacy_aggregates.enabled requires the complete signed Governance DAG publisher binding: peer id, runtime signer handle, revision, policy digest, and public key",
                ));
            }
        }
        let pop_credentials = self.pop_credentials.parse(self.enabled, emitter);
        let moderation_orchestrator = self.moderation_orchestrator.parse(self.enabled, emitter);
        let evidence_viewer = self.evidence_viewer.parse(self.enabled, emitter);
        let reputation_runtime = self.reputation_runtime.parse(
            self.enabled,
            self.reputation_trust_policy_path.as_deref(),
            emitter,
        );
        let reserve_transparency_runtime = self.reserve_transparency_runtime.parse(
            self.enabled,
            reputation_runtime.as_ref(),
            emitter,
        );
        let por_replay_archive =
            self.por_replay_archive
                .parse(self.enabled, reputation_runtime_enabled, emitter);
        let hedging_billing_runtime = self.hedging_billing_runtime.parse(
            self.enabled,
            self.hedging_feed_trust_policy_path.as_deref(),
            emitter,
        );
        let provider_ingest_runtime =
            self.provider_ingest_runtime
                .parse(self.enabled, provider_id.as_ref(), emitter);
        let governance_dag_service = self
            .governance_dag_service
            .parse(signed_local_governance_producer_configured, emitter);
        if governance_dag_service.publisher_public_key_hex.is_some()
            && governance_dag_service.publisher_public_key_hex
                != self.governance_dag_publisher_public_key_hex
        {
            emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(
                "sorafs.storage.governance_dag_service.publisher_public_key_hex must exactly match governance_dag_publisher_public_key_hex",
            ));
        }
        let stream_tokens = self
            .stream_tokens
            .parse(self.enabled, provider_id.is_some(), emitter);
        actual::SorafsStorage {
            enabled: self.enabled,
            provider_id,
            data_dir: self.data_dir,
            max_capacity_bytes: self.max_capacity_bytes,
            max_parallel_fetches: self.max_parallel_fetches,
            max_pins: self.max_pins,
            signer_journal_inventory: self.signer_journal_inventory.parse(emitter),
            por_sample_interval_secs: self.por_sample_interval_secs,
            pdp_sample_window: self.pdp_sample_window,
            pdp_tree_memory_limit_bytes: self.pdp_tree_memory_limit_bytes,
            moderation_screening_enabled: self.moderation_screening_enabled,
            moderation_screening_authority_bundle_path: self
                .moderation_screening_authority_bundle_path,
            moderation_screening_authority_bundle_digest,
            moderation_quarantine_key_provider,
            pop_credentials,
            moderation_orchestrator,
            evidence_viewer,
            reputation_runtime,
            reserve_transparency_runtime,
            por_replay_archive,
            hedging_billing_runtime,
            provider_ingest_runtime,
            pdp_provider: self.pdp_provider.parse(emitter),
            runtime: self.runtime.parse(emitter),
            alias: self.alias.or_else(super::defaults::sorafs::storage::alias),
            adverts: self.adverts.parse(),
            metering_smoothing: self.metering_smoothing.parse(),
            stream_tokens,
            native_transaction_signers,
            orderbook_worker: self.orderbook_worker.parse(emitter),
            reserve_worker: self.reserve_worker.parse(emitter),
            reputation_trust_policy_path: self.reputation_trust_policy_path,
            hedging_feed_trust_policy_path: self.hedging_feed_trust_policy_path,
            privacy_aggregates: self.privacy_aggregates.parse(emitter),
            evidence_viewer_audits: self.evidence_viewer_audits.parse(),
            governance_dag_dir: self.governance_dag_dir,
            governance_dag_publisher_peer_id: self.governance_dag_publisher_peer_id,
            governance_dag_signer_handle: self.governance_dag_signer_handle,
            governance_dag_signer_revision: self.governance_dag_signer_revision,
            governance_dag_signer_policy_digest,
            governance_dag_publisher_public_key_hex: self.governance_dag_publisher_public_key_hex,
            governance_dag_service,
        }
    }
}
/// Governance DAG public-service configuration and shared sealed producer state.
#[derive(Debug, ReadConfig, Clone, norito::JsonDeserialize)]
