impl SorafsPrivacyAggregateScheduleConfig {
    fn parse(self, emitter: &mut Emitter<ParseError>) -> actual::SorafsPrivacyAggregateSchedule {
        fn gcd(mut left: u64, mut right: u64) -> u64 {
            while right != 0 {
                let remainder = left % right;
                left = right;
                right = remainder;
            }
            left
        }
        let invalid = |message: String, emitter: &mut Emitter<ParseError>| {
            emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(message));
        };
        let parse_digest = |raw: &str, field: &str, emitter: &mut Emitter<ParseError>| {
            if raw.len() != 64
                || raw
                    .bytes()
                    .any(|byte| !byte.is_ascii_digit() && !(b'a'..=b'f').contains(&byte))
            {
                invalid(
                    format!(
                        "sorafs.storage.privacy_aggregates.{field} must be 64 lowercase hex characters"
                    ),
                    emitter,
                );
                return None;
            }
            let decoded = hex::decode(raw).expect("validated lowercase hex");
            let mut digest = [0_u8; 32];
            digest.copy_from_slice(&decoded);
            if digest == [0; 32] {
                invalid(
                    format!("sorafs.storage.privacy_aggregates.{field} must be nonzero"),
                    emitter,
                );
                return None;
            }
            Some(digest)
        };
        let parse_provider_binding =
            |field_prefix: &str,
             required: bool,
             handle: Option<&str>,
             revision: Option<u64>,
             policy_digest_hex: Option<&str>,
             emitter: &mut Emitter<ParseError>| {
                let any_configured =
                    handle.is_some() || revision.is_some() || policy_digest_hex.is_some();
                if !required {
                    if any_configured {
                        invalid(
                            format!(
                                "sorafs.storage.privacy_aggregates.{field_prefix} binding fields must be absent when the provider is not required"
                            ),
                            emitter,
                        );
                    }
                    return None;
                }
                if handle.is_none() || revision.is_none() || policy_digest_hex.is_none() {
                    invalid(
                        format!(
                            "sorafs.storage.privacy_aggregates.{field_prefix} handle, revision, and policy digest are required together"
                        ),
                        emitter,
                    );
                    return None;
                }
                let handle = handle.expect("required provider handle checked above");
                if !is_production_runtime_handle(handle) {
                    invalid(
                        format!(
                            "sorafs.storage.privacy_aggregates.{field_prefix}_handle must be a canonical non-test production handle"
                        ),
                        emitter,
                    );
                    return None;
                }
                let revision = revision.expect("required provider revision checked above");
                if revision == 0 {
                    invalid(
                        format!(
                            "sorafs.storage.privacy_aggregates.{field_prefix}_revision must be nonzero"
                        ),
                        emitter,
                    );
                    return None;
                }
                let policy_digest = parse_digest(
                    policy_digest_hex.expect("required provider policy digest checked above"),
                    &format!("{field_prefix}_policy_digest_hex"),
                    emitter,
                )?;
                Some(actual::SorafsTransparencyRuntimeProviderBinding {
                    handle: handle.to_owned(),
                    revision,
                    policy_digest,
                })
            };
        if self.aggregate_id_prefix.trim() != self.aggregate_id_prefix
            || self.aggregate_id_prefix.is_empty()
            || self.aggregate_id_prefix.len() > 128
            || self.aggregate_id_prefix.chars().any(char::is_control)
        {
            invalid(
                "sorafs.storage.privacy_aggregates.aggregate_id_prefix is invalid".to_string(),
                emitter,
            );
        }
        if self.cycle_seconds == 0 {
            invalid(
                "sorafs.storage.privacy_aggregates.cycle_seconds must be positive".to_string(),
                emitter,
            );
        }
        if self.enabled
            && (self.first_cycle_start_unix == 0
                || !self
                    .first_cycle_start_unix
                    .is_multiple_of(self.cycle_seconds.max(1)))
        {
            invalid(
                "sorafs.storage.privacy_aggregates.first_cycle_start_unix must be nonzero and cycle-aligned when enabled"
                    .to_string(),
                emitter,
            );
        }
        if !matches!(
            self.privacy_mode.as_str(),
            "differential_privacy" | "suppression" | "differential_privacy_with_suppression"
        ) {
            invalid(
                "sorafs.storage.privacy_aggregates.privacy_mode is invalid".to_string(),
                emitter,
            );
        }
        if self.epsilon_numerator == 0
            || self.epsilon_denominator == 0
            || gcd(self.epsilon_numerator, self.epsilon_denominator) != 1
        {
            invalid(
                "sorafs.storage.privacy_aggregates epsilon must be a reduced positive rational"
                    .to_string(),
                emitter,
            );
        }
        if self.per_subject_metric_cap == 0 || self.suppression_threshold == 0 {
            invalid(
                "sorafs.storage.privacy_aggregates contribution cap and suppression threshold must be positive"
                    .to_string(),
                emitter,
            );
        }
        if self.composition_budget_epsilon_numerator == 0
            || self.composition_budget_epsilon_denominator == 0
            || gcd(
                self.composition_budget_epsilon_numerator,
                self.composition_budget_epsilon_denominator,
            ) != 1
            || self.composition_budget_max_publications == 0
            || self.composition_budget_max_publications > 4_096
        {
            invalid(
                "sorafs.storage.privacy_aggregates composition budget is invalid".to_string(),
                emitter,
            );
        }
        let query_id = self
            .query_id_hex
            .as_deref()
            .and_then(|raw| parse_digest(raw, "query_id_hex", emitter));
        let policy_digest = self
            .policy_digest_hex
            .as_deref()
            .and_then(|raw| parse_digest(raw, "policy_digest_hex", emitter));
        let cycle_prf_provider = parse_provider_binding(
            "cycle_prf_provider",
            self.enabled && self.privacy_mode != "suppression",
            self.cycle_prf_provider_handle.as_deref(),
            self.cycle_prf_provider_revision,
            self.cycle_prf_provider_policy_digest_hex.as_deref(),
            emitter,
        );
        let release_anchor_provider = parse_provider_binding(
            "release_anchor_provider",
            self.enabled,
            self.release_anchor_provider_handle.as_deref(),
            self.release_anchor_provider_revision,
            self.release_anchor_provider_policy_digest_hex.as_deref(),
            emitter,
        );
        let leader_lease_provider = parse_provider_binding(
            "leader_lease_provider",
            self.enabled,
            self.leader_lease_provider_handle.as_deref(),
            self.leader_lease_provider_revision,
            self.leader_lease_provider_policy_digest_hex.as_deref(),
            emitter,
        );
        let fenced_privacy_publisher = parse_provider_binding(
            "fenced_privacy_publisher",
            self.enabled,
            self.fenced_privacy_publisher_handle.as_deref(),
            self.fenced_privacy_publisher_revision,
            self.fenced_privacy_publisher_policy_digest_hex.as_deref(),
            emitter,
        );
        let mut population_inventory = Vec::with_capacity(self.population_inventory.len());
        let mut previous_population: Option<(String, [u8; 32])> = None;
        let mut population_labels = BTreeSet::new();
        let mut population_digests = BTreeSet::new();
        if self.population_inventory.len() > 256 {
            invalid(
                "sorafs.storage.privacy_aggregates.population_inventory exceeds 256 entries"
                    .to_string(),
                emitter,
            );
        }
        for population in self.population_inventory {
            let valid_label = !population.label.is_empty()
                && population.label.trim() == population.label
                && population.label.len() <= 256
                && !population.label.chars().any(char::is_control);
            if !valid_label {
                invalid(
                    "sorafs.storage.privacy_aggregates population label is invalid".to_string(),
                    emitter,
                );
            }
            let Some(digest) = parse_digest(
                &population.digest_hex,
                "population_inventory.digest_hex",
                emitter,
            ) else {
                continue;
            };
            let key = (population.label.clone(), digest);
            if previous_population
                .as_ref()
                .is_some_and(|previous| previous >= &key)
                || !population_labels.insert(population.label.clone())
                || !population_digests.insert(digest)
            {
                invalid(
                    "sorafs.storage.privacy_aggregates.population_inventory must be unique and sorted"
                        .to_string(),
                    emitter,
                );
            }
            previous_population = Some(key);
            population_inventory.push(actual::SorafsPrivacyAggregatePopulation {
                label: population.label,
                digest,
            });
        }
        let mut metric_schema = Vec::with_capacity(self.metric_schema.len());
        let mut previous_metric_key: Option<String> = None;
        if self.metric_schema.len() > 256 {
            invalid(
                "sorafs.storage.privacy_aggregates.metric_schema exceeds 256 entries".to_string(),
                emitter,
            );
        }
        for metric in self.metric_schema {
            let valid_key = !metric.key.is_empty()
                && metric.key.trim() == metric.key
                && metric.key.len() <= 256
                && !metric.key.chars().any(char::is_control);
            let valid_unit = !metric.unit.is_empty()
                && metric.unit.trim() == metric.unit
                && metric.unit.len() <= 256
                && !metric.unit.chars().any(char::is_control);
            if !valid_key || !valid_unit {
                invalid(
                    "sorafs.storage.privacy_aggregates metric schema text is invalid".to_string(),
                    emitter,
                );
            }
            if previous_metric_key
                .as_ref()
                .is_some_and(|previous| previous >= &metric.key)
            {
                invalid(
                    "sorafs.storage.privacy_aggregates.metric_schema must be unique and sorted"
                        .to_string(),
                    emitter,
                );
            }
            previous_metric_key = Some(metric.key.clone());
            metric_schema.push(actual::SorafsPrivacyAggregateMetric {
                key: metric.key,
                unit: metric.unit,
            });
        }
        if self.enabled && policy_digest.is_none() {
            invalid(
                "sorafs.storage.privacy_aggregates.policy_digest_hex is required when enabled"
                    .to_string(),
                emitter,
            );
        }
        if self.enabled && query_id.is_none() {
            invalid(
                "sorafs.storage.privacy_aggregates.query_id_hex is required when enabled"
                    .to_string(),
                emitter,
            );
        }
        if self.enabled && population_inventory.is_empty() {
            invalid(
                "sorafs.storage.privacy_aggregates.population_inventory is required when enabled"
                    .to_string(),
                emitter,
            );
        }
        if self.enabled && metric_schema.is_empty() {
            invalid(
                "sorafs.storage.privacy_aggregates.metric_schema is required when enabled"
                    .to_string(),
                emitter,
            );
        }
        actual::SorafsPrivacyAggregateSchedule {
            enabled: self.enabled,
            cycle_seconds: self.cycle_seconds,
            first_cycle_start_unix: self.first_cycle_start_unix,
            publish_delay_seconds: self.publish_delay_seconds,
            aggregate_id_prefix: self.aggregate_id_prefix,
            query_id,
            population_inventory,
            metric_schema,
            privacy_mode: self.privacy_mode,
            epsilon_numerator: self.epsilon_numerator,
            epsilon_denominator: self.epsilon_denominator,
            per_subject_metric_cap: self.per_subject_metric_cap,
            suppression_threshold: self.suppression_threshold,
            policy_digest,
            cycle_prf_provider,
            release_anchor_provider,
            leader_lease_provider,
            fenced_privacy_publisher,
            composition_budget_epsilon_numerator: self.composition_budget_epsilon_numerator,
            composition_budget_epsilon_denominator: self.composition_budget_epsilon_denominator,
            composition_budget_max_publications: self.composition_budget_max_publications,
        }
    }
}
