impl SorafsPorDrand {
    fn parse(
        self,
        state_path: PathBuf,
        emitter: &mut Emitter<ParseError>,
    ) -> actual::SorafsPorDrand {
        fn decode_fixed<const N: usize>(
            value: &str,
            field: &str,
            emitter: &mut Emitter<ParseError>,
        ) -> [u8; N] {
            if value.is_empty() {
                return [0; N];
            }
            if value.len() != N * 2
                || !value
                    .bytes()
                    .all(|byte| matches!(byte, b'0'..=b'9' | b'a'..=b'f'))
            {
                emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(format!(
                    "sorafs.por.drand.{field} must be exactly {N} bytes of canonical lowercase hexadecimal"
                )));
                return [0; N];
            }
            let mut decoded = [0; N];
            if hex::decode_to_slice(value, &mut decoded).is_err() {
                emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(format!(
                    "sorafs.por.drand.{field} must be exactly {N} bytes of canonical lowercase hexadecimal"
                )));
                return [0; N];
            }
            decoded
        }
        actual::SorafsPorDrand {
            scheme: self.scheme,
            chain_hash: decode_fixed(&self.chain_hash_hex, "chain_hash_hex", emitter),
            public_key: decode_fixed(&self.public_key_hex, "public_key_hex", emitter),
            genesis_time: self.genesis_time,
            period_secs: self.period_secs,
            endpoints: self.endpoints,
            quorum: self.quorum,
            max_endpoints: self.max_endpoints,
            connect_timeout: std::time::Duration::from_millis(self.connect_timeout_ms),
            request_timeout: std::time::Duration::from_millis(self.request_timeout_ms),
            max_body_bytes: self.max_body_bytes,
            max_beacon_age_secs: self.max_beacon_age_secs,
            max_future_skew_secs: self.max_future_skew_secs,
            state_path,
        }
    }
}
