/// User-level configuration for the `SoraFS` gateway policy and automation surface.
#[derive(Debug, ReadConfig, Clone, norito::JsonDeserialize)]
pub struct SorafsGateway {
    /// Require manifest envelopes on incoming requests.
    #[config(default = "defaults::sorafs::gateway::REQUIRE_MANIFEST_ENVELOPE")]
    pub require_manifest_envelope: bool,
    /// Enforce admission registry membership checks.
    #[config(default = "defaults::sorafs::gateway::ENFORCE_ADMISSION")]
    pub enforce_admission: bool,
    /// Enforce advertised capabilities before serving data.
    #[config(default = "defaults::sorafs::gateway::ENFORCE_CAPABILITIES")]
    pub enforce_capabilities: bool,
    /// Directory containing `SoraNet` salt announcements (Norito JSON files).
    pub salt_schedule_dir: Option<PathBuf>,
    /// Named static-site bindings loaded and cached when Torii starts.
    #[config(nested)]
    pub site_bindings: SorafsGatewaySiteBindings,
    /// Rolling-window rate limiting configuration.
    #[config(nested)]
    pub rate_limit: SorafsGatewayRateLimit,
    /// ACME automation configuration.
    #[config(nested)]
    pub acme: SorafsGatewayAcme,
    /// Governed signed compliance controller configuration.
    #[config(nested)]
    pub compliance: SorafsGatewayCompliance,
    /// High-level rollout phase controlling the default anonymity policy.
    #[config(default = "defaults::sorafs::gateway::rollout_phase()")]
    pub rollout_phase: String,
    /// Optional staged anonymity policy override for `SoraNet` transports.
    pub anonymity_policy: Option<String>,
    /// Untrusted per-CID host routing configuration.
    #[config(nested)]
    pub untrusted_hosting: SorafsGatewayUntrustedHosting,
    /// Optional direct-mode override configuration.
    pub direct_mode: Option<SorafsGatewayDirectMode>,
}
impl Default for SorafsGateway {
    fn default() -> Self {
        Self {
            require_manifest_envelope: defaults::sorafs::gateway::REQUIRE_MANIFEST_ENVELOPE,
            enforce_admission: defaults::sorafs::gateway::ENFORCE_ADMISSION,
            enforce_capabilities: defaults::sorafs::gateway::ENFORCE_CAPABILITIES,
            salt_schedule_dir: None,
            site_bindings: SorafsGatewaySiteBindings::default(),
            rate_limit: SorafsGatewayRateLimit::default(),
            acme: SorafsGatewayAcme::default(),
            compliance: SorafsGatewayCompliance::default(),
            rollout_phase: defaults::sorafs::gateway::rollout_phase(),
            anonymity_policy: defaults::sorafs::gateway::anonymity_policy(),
            untrusted_hosting: SorafsGatewayUntrustedHosting::default(),
            direct_mode: None,
        }
    }
}
impl SorafsGateway {
    fn parse(self, emitter: &mut Emitter<ParseError>) -> actual::SorafsGateway {
        let Self {
            require_manifest_envelope,
            enforce_admission,
            enforce_capabilities,
            salt_schedule_dir,
            site_bindings,
            rate_limit,
            acme,
            compliance,
            rollout_phase,
            anonymity_policy,
            untrusted_hosting,
            direct_mode,
        } = self;
        let rollout_phase = iroha_service_model::soranet::RolloutPhase::parse(&rollout_phase)
            .unwrap_or_else(|| {
                emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(format!(
                    "invalid `sorafs.gateway.rollout_phase` value `{rollout_phase}`; expected exactly canary|ramp|default"
                )));
                iroha_service_model::soranet::RolloutPhase::default()
            });
        let anonymity_policy = anonymity_policy.map_or_else(
            || rollout_phase.default_anonymity_policy(),
            |label| iroha_service_model::soranet::AnonymityPolicy::parse(&label).unwrap_or_else(|| {
                    emitter.emit(Report::new(ParseError::InvalidSorafsConfig).attach(format!(
                        "invalid `sorafs.gateway.anonymity_policy` value `{label}`; expected exactly anon-guard-pq|anon-majority-pq|anon-strict-pq"
                    )));
                    rollout_phase.default_anonymity_policy()
                }),
        );
        actual::SorafsGateway {
            require_manifest_envelope,
            enforce_admission,
            enforce_capabilities,
            salt_schedule_dir,
            site_bindings: site_bindings.parse(),
            rate_limit: rate_limit.parse(),
            untrusted_hosting: untrusted_hosting.parse(),
            acme: acme.parse(emitter),
            compliance: compliance.parse(emitter),
            rollout_phase,
            anonymity_policy: Some(anonymity_policy),
            direct_mode: direct_mode.map(SorafsGatewayDirectMode::parse),
        }
    }
}
#[cfg(test)]
mod sorafs_gateway_label_config_tests {
    use super::*;

    #[test]
    fn canonical_gateway_labels_parse_exactly() {
        for (rollout_label, expected_rollout, anonymity_label, expected_anonymity) in [
            (
                "canary",
                iroha_service_model::soranet::RolloutPhase::Canary,
                "anon-guard-pq",
                iroha_service_model::soranet::AnonymityPolicy::GuardPq,
            ),
            (
                "ramp",
                iroha_service_model::soranet::RolloutPhase::Ramp,
                "anon-majority-pq",
                iroha_service_model::soranet::AnonymityPolicy::MajorityPq,
            ),
            (
                "default",
                iroha_service_model::soranet::RolloutPhase::Default,
                "anon-strict-pq",
                iroha_service_model::soranet::AnonymityPolicy::StrictPq,
            ),
        ] {
            let mut emitter = Emitter::new();
            let parsed = SorafsGateway {
                rollout_phase: rollout_label.to_owned(),
                anonymity_policy: Some(anonymity_label.to_owned()),
                ..SorafsGateway::default()
            }
            .parse(&mut emitter);

            assert!(emitter.into_result().is_ok(), "{rollout_label}");
            assert_eq!(parsed.rollout_phase, expected_rollout);
            assert_eq!(parsed.anonymity_policy, Some(expected_anonymity));
        }
    }

    #[test]
    fn invalid_gateway_labels_accumulate_diagnostics_without_unwinding() {
        let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            let mut emitter = Emitter::new();
            let parsed = SorafsGateway {
                rollout_phase: " Canary".to_owned(),
                anonymity_policy: Some("ANON-GUARD-PQ".to_owned()),
                ..SorafsGateway::default()
            }
            .parse(&mut emitter);
            let diagnostic = format!(
                "{:?}",
                emitter
                    .into_result()
                    .expect_err("non-canonical gateway labels must emit diagnostics")
            );
            (parsed, diagnostic)
        }));

        let (parsed, diagnostic) =
            result.expect("ordinary SoraFS gateway configuration errors must not unwind");
        assert_eq!(
            parsed.rollout_phase,
            iroha_service_model::soranet::RolloutPhase::Canary
        );
        assert_eq!(
            parsed.anonymity_policy,
            Some(iroha_service_model::soranet::AnonymityPolicy::GuardPq)
        );
        assert!(
            diagnostic.contains("sorafs.gateway.rollout_phase"),
            "{diagnostic}"
        );
        assert!(
            diagnostic.contains("sorafs.gateway.anonymity_policy"),
            "{diagnostic}"
        );
    }
}
